/****** Object:  UserDefinedFunction [dbo].[fnc_strSplit]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fnc_strSplit] (
    @string NVARCHAR(4000)
    ,@splitter CHAR(1)
)
RETURNS @res TABLE (
    id INT PRIMARY KEY
    ,RANK INT
    ,val NVARCHAR(4000)
)
AS
/*
Created:
Task: Split string by character.
DB:
Original: 

Revisions:  
Param's Explanation:

*/
BEGIN
    IF SUBSTRING(@string, LEN(@string), 1) <> @splitter
    BEGIN
	   SET @string = @string + @splitter
    END

    DECLARE @start INT
        ,@word NVARCHAR(4000)
        ,@charindex INT
        ,@i INT

    SET @i = 1
    SET @start = 1
    SET @charindex = CHARINDEX(@splitter, @string, @start)

    WHILE (@charindex <> 0)
    BEGIN
	   SET @word = SUBSTRING(@string, @start, @charindex - @start)
	   SET @start = @charindex + 1
	   SET @charindex = CHARINDEX(@splitter, @string, @start)

	   INSERT INTO @res
	   VALUES (
		  @start
		  ,@i
		  ,LTRIM(RTRIM(@word))
	   )

	   SET @i = @i + 1
    END

    RETURN
END



GO
