CREATE PROCEDURE [dbo].[Department_GetByModifiedDate] 
	 @FromDate DATETIME = NULL
AS
/*
Created: 20230220@Quinn.Vo
Task: Get department by last modified date.
DB: HRM
Original:

Revisions:
Param's Explanation:

*/
BEGIN
	SET NOCOUNT ON;

	IF @FromDate IS NULL
	BEGIN
		SELECT @FromDate = DATEADD(YYYY, -10, GETDATE())
	END

	SELECT [DepartmentId]
      ,[Code]
      ,[Name]
      ,[UnitId]
      ,[IsActive]
      ,[ModifiedDate]
      ,[IsDeleted]
	FROM dbo.Department as d WITH (NOLOCK) 
	WHERE ModifiedDate > @FromDate
	
END



