		AND dis.WorkDate = dig.WorkDate
		AND dig.IsIgnoredAbsent = 1
		INNER JOIN dbo.DisciplineIgnoreDetail AS dd WITH (NOLOCK) ON dis.EmpId = dd.EmpId
		AND dis.WorkDate = dd.WorkDate
