			,[ToDate1] = @ToDate1
			,[Contract2] = @Contract2
			,[FromDate2] = @FromDate2
			,[ToDate2] = @ToDate2
			,[Contract3] = @Contract3
			,[FromDate3] = @FromDate3
			,[ToDate3] = @ToDate3
			,[Contract4] = @Contract4
			,[FromDate4] = @FromDate4
			,[ToDate4] = @ToDate4
			,[Contract5] = @Contract5
			,[FromDate5] = @FromDate5
			,[ToDate5] = @ToDate5
			,[History] = @History
		WHERE [EmpId] = @EmpId

		COMMIT TRANSACTION;

		SELECT @ErrCode = 0
			,@ErrCode = ''
	END TRY

	BEGIN CATCH
		ROLLBACK TRANSACTION

		SELECT @ErrCode = 100
			,@ErrMsg = N'Update failed';
	END CATCH
END


