/****** Object:  StoredProcedure [dbo].[EmployeeAttendance_ForWaitingCase]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[EmployeeAttendance_ForWaitingCase]
AS
BEGIN
	SET XACT_ABORT ON;

	DECLARE @i INT
		,@TempEmpId INT
		,@TempWorkDate DATE
		,@TempShiftId INT
		,@fromDate DATE
		,@toDate DATE
	DECLARE @tblEmployee TABLE (
		Id INT PRIMARY KEY IDENTITY(1, 1)
		,EmpId INT
		,WorkDate DATE
		)

	SELECT @fromDate = MIN(tmpAtt.WorkDate)
		,@toDate = MAX(tmpAtt.WorkDate)
	FROM dbo.tmpEmployeeAttendace AS tmpAtt WITH (NOLOCK)

	INSERT INTO @tblEmployee (
		EmpId
		,WorkDate
		)
	SELECT TOP 100 EmpId
		,WorkDate
	FROM dbo.tmpEmployeeAttendace AS tmpAtt WITH (NOLOCK)

	DELETE tmp
	FROM dbo.tmpEmployeeAttendace AS tmp
		INNER JOIN @tblEmployee AS e ON tmp.EmpId = e.EmpId
		AND tmp.WorkDate = e.WorkDate

	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#TimeRecord'
			)
	BEGIN
		DROP TABLE #TimeRecord
	END

	CREATE TABLE #TimeRecord (
		Id INT
		,EmpId INT
		,RecordTime DATETIME
		,InOutType TINYINT
		)

	-- Get all in/out data into temp table to calculate
	INSERT INTO #TimeRecord (
		Id
		,EmpId
		,RecordTime
		,InOutType
		)
	SELECT Id
		,EmpId
		,RecordTime
		,InOutType
	FROM dbo.TimeRecord AS ti WITH (NOLOCK)
	WHERE RecordTime BETWEEN DATEADD(HH, - 2, CONVERT(VARCHAR(10), @fromDate, 111))
			AND DATEADD(d, 2, CONVERT(VARCHAR(10), @toDate, 111))
		AND EXISTS (
			SELECT 1
			FROM @tblEmployee
			WHERE EmpId = ti.EmpId
			)

	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#LeaveRequestHalfDay'
			)
	BEGIN
		DROP TABLE #LeaveRequestHalfDay
	END

	CREATE TABLE #LeaveRequestHalfDay (
		EmpId INT
		,OnDate DATETIME
		,FromTime DATETIME
		,ToTime DATETIME
		)

	-- Get all leave request half day
	INSERT INTO #LeaveRequestHalfDay (
		EmpId
		,OnDate
		,FromTime
		,ToTime
		)
	SELECT lv.EmpId
		,lv.OnDate
		,FromTime
		,ToTime
	FROM LeaveRequestDetail lv
		INNER JOIN (
		SELECT ldt.empId
			,OnDate
		FROM LeaveRequestDetail AS ldt
			INNER JOIN dbo.WorkingTimeRequest AS wrq ON ldt.RequestId = wrq.RequestId
		WHERE WorkType = 2
			AND IsHalfDay = 1 -- 2: leave, 1: Half day
			AND DATEDIFF(DD, @fromDate, OnDate) >= 0
			AND DATEDIFF(DD, OnDate, DATEADD(DD, 2, @toDate)) >= 0
			AND EXISTS (
				SELECT 1
				FROM @tblEmployee
				WHERE EmpId = ldt.EmpId
				)
			AND wrq.CurrentStatus IN (4, 6)
		GROUP BY ldt.empId
			,OnDate
		HAVING COUNT(1) = 1
		) a ON (
			a.EmpId = lv.EmpId
			AND a.OnDate = lv.OnDate
			)
		INNER JOIN dbo.WorkingTimeRequest AS rq WITH (NOLOCK) ON lv.RequestId = rq.RequestId
	WHERE lv.IsHalfDay = 1
		AND EXISTS (
			SELECT 1
			FROM @tblEmployee
			WHERE EmpId = lv.EmpId
			)
		AND rq.CurrentStatus IN (4, 6)

	-- Get all calendars of employees into temp table
	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#EmpCalendar'
			)
	BEGIN
		DROP TABLE #EmpCalendar
	END

	CREATE TABLE #EmpCalendar (
		Id INT PRIMARY KEY IDENTITY(1, 1)
		,EmpId INT
		,WorkDate DATETIME
		,ShiftId INT
		,IsHoliday BIT
		,IsOffDay BIT
		,IsLeaveDay BIT
		,LeaveTypeId INT NULL
		,IsKeepInView BIT
		,LateIn INT
		,EarlyOut INT
		,RequestedCheckInTime DATETIME
		,RequestedCheckOutTime DATETIME
		,BeginCheckInTime DATETIME
		,EndCheckInTime DATETIME
		,BeginCheckOutTime DATETIME
		,EndCheckOutTime DATETIME
		,BreakTimeMins INT
		,LeaveDay DECIMAL(18, 1)
		)

	INSERT INTO #EmpCalendar (
		EmpId
		,WorkDate
		,ShiftId
		,IsHoliday
		,IsOffDay
		,IsLeaveDay
		,LeaveTypeId
		,IsKeepInView
		,LateIn
		,EarlyOut
		,RequestedCheckInTime
		,RequestedCheckOutTime
		,BeginCheckInTime
		,EndCheckInTime
		,BeginCheckOutTime
		,EndCheckOutTime
		,BreakTimeMins
		,LeaveDay
		)
	SELECT e.EmpId
		,e.WorkDate
		,ec.ShiftId
		,IsHoliday
		,IsOffDay
		,IsLeaveDay
		,LeaveTypeId
		,IsKeepInView
		,LateIn
		,EarlyOut
		,RequestedCheckinTime
		,RequestedCheckoutTime
		,CASE 
			WHEN IsInAfterDay = 1 THEN DATEADD(D, 1, ec.WorkDate + ' ' + s.EndCheckInTime)
			ELSE CAST(ec.WorkDate + ' ' + s.EndCheckInTime AS DATETIME)
			END AS BeginCheckInTime
		,CASE 
			WHEN IsInAfterDay = 1 THEN DATEADD(d, 1, ec.WorkDate + ' ' + s.EndCheckInTime)
			ELSE CAST(ec.WorkDate + ' ' + s.EndCheckInTime AS DATETIME)
			END AS EndCheckInTime
		,CASE 
			WHEN IsOutAfterDay = 1 THEN DATEADD(d, 1, ec.WorkDate + ' ' + s.BeginCheckOutTime)
			ELSE CAST(ec.WorkDate + ' ' + s.BeginCheckOutTime AS DATETIME)
			END AS BeginCheckOutTime
		,CASE 
			WHEN IsOutAfterDay = 1 THEN DATEADD(d, 1, ec.WorkDate + ' ' + s.EndCheckOutTime)
			ELSE CAST(ec.WorkDate + ' ' + s.EndCheckOutTime AS DATETIME)
			END AS EndCheckOutTime
		,BreakTimeMins
		,LeaveDay
	FROM @tblEmployee AS e
		LEFT JOIN dbo.EmployeeCalendar AS ec WITH (NOLOCK) ON ec.EmpId = e.EmpId
		AND ec.WorkDate = e.WorkDate
		LEFT JOIN dbo.Shift s WITH (NOLOCK) ON s.ShiftId = ec.ShiftId
	ORDER BY e.EmpId
		,e.WorkDate

	IF EXISTS (
			SELECT 1
			FROM #EmpCalendar
			)
	BEGIN
		SET @i = 1

		WHILE EXISTS (
				SELECT 1
				FROM #EmpCalendar
				WHERE Id = @i
				)
		BEGIN
			SELECT @TempEmpId = EmpId
				,@TempWorkDate = WorkDate
				,@TempShiftId = ShiftId
			FROM #EmpCalendar
			WHERE Id = @i

			EXEC dbo.EmployeeAttendance_ProcessingAndInsert_ForEmpId @TempEmpId
				,@TempWorkDate
				,@TempWorkDate
				,1

			EXEC dbo.Discipline_Insert @TempWorkDate
				,@TempWorkDate
				,@TempEmpId

			SET @i = @i + 1
		END
	END

	DROP TABLE #TimeRecord

	DROP TABLE #EmpCalendar

	DROP TABLE #LeaveRequestHalfDay
END



GO
/****** Object:  StoredProcedure [dbo].[EmployeeAttendance_GetByType]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[EmployeeAttendance_GetByType] @fromtime DATE
	,@totime DATE
	,@EmpId INT = NULL
	,@TeamIds VARCHAR(MAX) = ''
	,@excludeUserDelete INT = 1
	,@isLocal BIT = NULL
	,@SupervisorId INT = NULL
	,@type SMALLINT
	,@isRealDate BIT = 0
AS
/*
Created: Tom.Vo@2013-10-31
Task: get attentance list of employees by type
DB: HRM_SMS
Original:

Revisions:
	- Merlin.Le@20200713: Get section and department - Redmine Id: 110683
Param's Explanation:
	@type: 0-all, 1-missing checkin; 2-missing check out, 3: latein; 4-earlyout, 5- not work
*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @today DATETIME
		,@now DATETIME
		,@StartDate DATETIME
		,@EndDate DATETIME
		,@employeeIds VARCHAR(MAX)
		-- request type
		,@LateInRequestTypeId TINYINT = 3
		,@EarlyOutRequestTypeId TINYINT = 4
		,@ChangeShiftRequestTypeId TINYINT = 5
		,@LeaveRequestTypeId TINYINT = 6
		,@KeepInViewRequestTypeId TINYINT = 7
		-- request status
		,@NotVerifiedStatusId TINYINT = 3
		,@RejectedStatusId TINYINT = 5
		,@VoidStatusId TINYINT = 7
	CREATE TABLE #tmpGroup (GroupId INT PRIMARY KEY)

	CREATE TABLE #tmpEmployee (EmpId INT PRIMARY KEY)

	IF (@isRealDate = 1)
	BEGIN
		SET @fromtime = DATEADD(d, - 1, @fromtime)
	END

	IF ISNULL(@TeamIds, '') <> ''
	BEGIN
		INSERT INTO #tmpGroup (GroupId)
		SELECT val
		FROM dbo.fnc_strSplit(@TeamIds, ',')
	END
	ELSE
	BEGIN
		INSERT INTO #tmpGroup (GroupId)
		SELECT GroupId
		FROM dbo.[Group] WITH (NOLOCK)
		WHERE ISNULL(IsDeleted, 0) = 0
	END

	IF @EmpId IS NULL
	BEGIN
		INSERT INTO #tmpEmployee (EmpId)
		SELECT DISTINCT EmpId
		FROM dbo.fnc_GetEmployeeByActorId(@SupervisorId, @excludeUserDelete, 1)
	END
	ELSE
	BEGIN
		INSERT INTO #tmpEmployee (EmpId)
		VALUES (@EmpId)
	END

	SET @now = dateadd(hh, 7, GETUTCDATE())
	SET @today = convert(VARCHAR(10), @now, 111) -- use UTC because the server use GMT-4

	CREATE TABLE #tmpDailyRequest (
		RequestId BIGINT
		,EmpId INT
		,WorkDate DATE
		,RequestType INT
		,InOutMins INT
		,RequestDate DATETIME
		,FromDate DATETIME
		,ToDate DATETIME
		,FromTime DATETIME
		,ToTime DATETIME
		,FromShift INT
		,ToShift INT
		,TotalDays NUMERIC(18, 2)
		,CurrentStatus TINYINT
		,KeepInViewTypeId TINYINT
		,Remark NVARCHAR(2000)
		,CreatedDate DATETIME
		,LeaveTypeId INT
		)

	SELECT @employeeIds = COALESCE(@employeeIds + ',', '') + CAST(EmpId AS VARCHAR(20))
	FROM #tmpEmployee WITH (NOLOCK)

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @fromtime
		,@toDate = @totime
		,@empIds = @employeeIds

	-- check in/out
	INSERT INTO #tmpDailyRequest (
		RequestDate
		,RequestId
		,EmpId
		,RequestType
		,FromDate
		,ToDate
		,TotalDays
		,CurrentStatus
		,Remark
		,CreatedDate
		)
	SELECT cio.RequestTime
		,r.RequestId
		,r.EmpId
		,r.RequestType
		,cio.OnDate
		,cio.OnDate
		,0
		,r.CurrentStatus
		,r.Remark
		,r.CreatedDate
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN dbo.CheckInOutRequest AS cio WITH (NOLOCK) ON r.RequestId = cio.RequestId
		AND cio.OnDate BETWEEN @fromtime
			AND @totime
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
	WHERE EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)

	-- late in/early out
	INSERT INTO #tmpDailyRequest (
		RequestId
		,EmpId
		,RequestType
		,FromDate
		,ToDate
		,TotalDays
		,InOutMins
		,CurrentStatus
		,Remark
		,CreatedDate
		)
	SELECT r.RequestId
		,r.EmpId
		,r.RequestType
		,lieo.OnDate
		,lieo.OnDate
		,0
		,(CASE 
			WHEN r.RequestType = @LateInRequestTypeId THEN lieo.LateInMins
			ELSE lieo.EarlyOutMins END
			)
		,r.CurrentStatus
		,r.Remark
		,r.CreatedDate
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN dbo.LateInEarlyOutRequest AS lieo WITH (NOLOCK) ON r.RequestId = lieo.RequestId
		AND lieo.OnDate BETWEEN @fromtime
			AND @totime
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
	WHERE EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)

	-- keep in view
	INSERT INTO #tmpDailyRequest (
		RequestId
		,EmpId
		,RequestType
		,FromDate
		,ToDate
		,FromTime
		,ToTime
		,TotalDays
		,CurrentStatus
		,KeepInViewTypeId
		,Remark
		,CreatedDate
		)
	SELECT r.RequestId
		,r.EmpId
		,r.RequestType
		,kiv.OnDate
		,kiv.OnDate
		,kiv.FromTime
		,kiv.ToTime
		,(CASE 
			WHEN kiv.IsHalfDay = 1 THEN 0.5
			ELSE 1 END
			)
		,r.CurrentStatus
		,kiv.KeepInViewType
		,r.Remark
		,r.CreatedDate
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON r.RequestId = kiv.RequestId
		AND kiv.OnDate BETWEEN @fromtime
			AND @totime
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
	WHERE EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)

	-- Leave request
	INSERT INTO #tmpDailyRequest (
		RequestId
		,EmpId
		,RequestType
		,FromDate
		,ToDate
		,TotalDays
		,CurrentStatus
		,Remark
		,CreatedDate
		,LeaveTypeId
		)
	SELECT DISTINCT r.RequestId
		,r.EmpId
		,r.RequestType
		,lr.FromDate
		,lr.ToDate
		,lr.TotalDays
		,CurrentStatus
		,r.Remark
		,r.CreatedDate
		,lr.LeaveType
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN dbo.LeaveRequest AS lr WITH (NOLOCK) ON r.RequestId = lr.RequestId
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
	WHERE (
			(
				lr.FromDate BETWEEN @fromtime
					AND @totime
				AND lr.ToDate >= @totime
				)
			OR (
				lr.FromDate <= @fromtime
				AND lr.ToDate >= @totime
				)
			OR lr.ToDate BETWEEN @fromtime
				AND @totime
			)
		AND EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)
		AND NOT EXISTS (
			SELECT 1
			FROM dbo.LeaveRequestDetail AS ldt WITH (NOLOCK)
			WHERE lr.RequestId = ldt.RequestId
			)

	-- Leave request
	INSERT INTO #tmpDailyRequest (
		RequestId
		,EmpId
		,WorkDate
		,RequestType
		,FromDate
		,ToDate
		,TotalDays
		,FromTime
		,ToTime
		,CurrentStatus
		,Remark
		,CreatedDate
		,LeaveTypeId
		)
	SELECT DISTINCT r.RequestId
		,r.EmpId
		,ldt.OnDate
		,r.RequestType
		,lr.FromDate
		,lr.ToDate
		,lr.TotalDays
		,CASE WHEN ldt.IsHalfDay = 1 THEN ldt.FromTime ELSE NULL END
		,CASE WHEN ldt.IsHalfDay = 1 THEN ldt.ToTime ELSE NULL END
		,r.CurrentStatus
		,r.Remark
		,r.CreatedDate
		, ldt.LeaveType
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN [dbo].LeaveRequest AS lr WITH (NOLOCK) ON r.RequestId = lr.RequestId
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
		INNER JOIN dbo.LeaveRequestDetail AS ldt WITH (NOLOCK) ON lr.RequestId = ldt.RequestId
		AND ldt.WorkType IN (1, 2) -- off, leave
	WHERE (
			(
				datediff(d, @fromtime, lr.FromDate) <= 0
				AND datediff(d, @totime, lr.ToDate) >= 0
				)
			OR (
				datediff(d, @fromtime, lr.FromDate) >= 0
				AND datediff(d, @totime, lr.FromDate) <= 0
				)
			OR (
				datediff(d, @fromtime, lr.ToDate) >= 0
				AND datediff(d, @totime, lr.ToDate) <= 0
				)
			)
		AND EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)

	-- change shift
	INSERT INTO #tmpDailyRequest (
		RequestId
		,empid
		,RequestType
		,FromDate
		,ToDate
		,TotalDays
		,FromShift
		,ToShift
		,CurrentStatus
		,Remark
		,CreatedDate
		)
	SELECT r.RequestId
		,r.EmpId
		,r.RequestType
		,cs.FromDate
		,cs.ToDate
		,COUNT(1) TotalDays
		,MAX(csd.FromShift) FromShift
		,MAX(csd.ToShift) ToShift
		,r.CurrentStatus
		,r.Remark
		,r.CreatedDate
	FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
		INNER JOIN dbo.ChangeShiftRequest AS cs WITH (NOLOCK) ON r.RequestId = cs.RequestId
		AND r.CurrentStatus NOT IN (@NotVerifiedStatusId, @RejectedStatusId, @VoidStatusId)
		INNER JOIN dbo.ChangeShiftRequestDetail AS csd WITH (NOLOCK) ON csd.RequestId = cs.RequestId
	WHERE (
			(
				cs.FromDate BETWEEN @fromtime
					AND @totime
				AND cs.ToDate >= @totime
				)
			OR (
				cs.FromDate <= @fromtime
				AND cs.ToDate >= @totime
				)
			OR cs.ToDate BETWEEN @fromtime
				AND @totime
			)
		AND EXISTS (
			SELECT 1
			FROM #tmpEmployee AS emp WITH (NOLOCK)
			WHERE r.EmpId = emp.EmpId
			)
	GROUP BY r.CreatedDate
		,r.RequestId
		,r.EmpId
		,r.RequestType
		,cs.FromDate
		,cs.ToDate
		,r.CurrentStatus
		,r.Remark

	IF (@isRealDate = 1)
	BEGIN
		SET @fromtime = DATEADD(d, 1, @fromtime)
	END

	SET @StartDate = @fromtime
	SET @EndDate = @totime

	WHILE DATEPART(dw, @StartDate) <> 2
	BEGIN
		SET @StartDate = DATEADD(d, - 1, @StartDate)
	END

	WHILE DATEPART(dw, @EndDate) <> 1
	BEGIN
		SET @EndDate = DATEADD(d, 1, @EndDate)
	END

	DECLARE @OutOffDay TABLE (
		WorkDate DATETIME
		,EmpId INT
		)
	DECLARE @StartDate_tmp DATETIME
		,@EndDate_tmp DATETIME

	WHILE @StartDate <= @EndDate
	BEGIN
		SET @StartDate_tmp = @StartDate
		SET @EndDate_tmp = DATEADD(d, 6, @StartDate)
		SET @StartDate = DATEADD(d, 7, @StartDate)

		INSERT INTO @OutOffDay (
			WorkDate
			,EmpId
			)
		SELECT WorkDate
			,cl.EmpId
		FROM dbo.EmployeeCalendar AS cl WITH (NOLOCK)
			INNER JOIN (
			SELECT c.EmpId
			FROM dbo.EmployeeCalendar AS c WITH (NOLOCK)
				INNER JOIN dbo.EmployeeSummary AS es WITH (NOLOCK) ON c.EmpId = es.EmpId
			WHERE WorkDate BETWEEN @StartDate_tmp
					AND @EndDate_tmp
				AND c.IsOffDay = 1
				AND (
					@EmpId IS NULL
					OR c.EmpId = @EmpId
					)
			GROUP BY c.EmpId
				,es.OffDaysbyWeek
			HAVING COUNT(c.EmpId) > es.OffDaysbyWeek
			) AS a ON cl.EmpId = a.EmpId
		WHERE WorkDate BETWEEN @StartDate_tmp
				AND @EndDate_tmp
			AND cl.IsOffDay = 1
			AND (
				@EmpId IS NULL
				OR cl.EmpId = @EmpId
				)
	END

	SELECT T.Code
		,T.EmpId
		,T.FullName
		,T.NickName
		,T.[Team]
		,T.[TeamCode]
		,T.[Rank]
		,T.AttendanceDate
		,T.ShiftId
		,COALESCE(T.ShiftCode, CASE 
				WHEN ISNULL(T.IsHoliday, 0) = 0
					AND (T.ShiftId IS NULL OR T.ShiftId = -1)
					AND isOffday = 1 THEN 'Off day'
				WHEN ISNULL(T.IsHoliday, 0) = 1
					AND (
						T.InFixed IS NULL
						AND T.OutFixed IS NULL
						) THEN 'PH'
				ELSE ''
				END, '') ShiftCode
		,T.ExpectedInTime
		,T.ExpectedOutTime
		,CASE 
			WHEN T.IsShiftCrossDay = 1
				AND ISNULL(T.IsHoliday, 0) = 0
				AND T.ShiftId IS NULL
				AND isOffday = 1 THEN NULL
			ELSE T.InFixed
			END InFixed
		,CASE 
			WHEN T.IsShiftCrossDay = 1
				AND ISNULL(T.IsHoliday, 0) = 0
				AND T.ShiftId IS NULL
				AND isOffday = 1 THEN NULL
			ELSE T.OutFixed
			END OutFixed
		,T.LateIn
		,T.EarlyOut
		,CASE 
			WHEN T.IsShiftCrossDay = 1
				AND ISNULL(T.IsHoliday, 0) = 0
				AND T.ShiftId IS NULL
				AND isOffday = 1 THEN NULL
			ELSE T.TotalWorkHours
			END TotalWorkHours
		,T.Absence
		,T.isNotWork
		,T.isOffday
		,T.IsHoliday AS IsPublicHoliday
		,(CASE 
			WHEN (
					(
						od.EmpId IS NOT NULL
						OR (
							AttendanceDate1 IS NOT NULL
							AND isMissingCheckin = 1
							)
						OR (
							AttendanceDate1 IS NOT NULL
							AND isMissingCheckOut = 1
							)
						)
					AND CONVERT(NVARCHAR(20), T.AttendanceDate1, 111) < CONVERT(NVARCHAR(20), GETDATE(), 111)
					) THEN 1
			ELSE 0 END
			) AS IsWarning
		,T.IsOvertime
		,T.OvertimeHours
		,T.OvertimeStatus
		,ISNULL(stuff((CASE 
					WHEN AttendanceDate1 IS NOT NULL
						AND (
							isLateIn = 1
							AND LateIn > 0
							) THEN (', Late In')
					ELSE '' END
					) + (CASE 
					WHEN AttendanceDate1 IS NOT NULL
						AND (
							isEarlyOut = 1
							AND EarlyOut > 0
							) THEN ', Early Out'
					ELSE '' END
					) + (CASE 
					WHEN AttendanceDate1 IS NOT NULL
						AND isMissingCheckin = 1 THEN ', Missing Check-in'
					ELSE '' END
					) + (CASE 
					WHEN AttendanceDate1 IS NOT NULL
						AND isMissingCheckOut = 1
						AND CONVERT(NVARCHAR(20), T.AttendanceDate1, 111) < CONVERT(NVARCHAR(20), GETDATE(), 111) THEN ', Missing Check-out'
					ELSE '' END
					) + (CASE 
					WHEN AttendanceDate1 IS NOT NULL
						AND IsKeepInView = 1 THEN ', CL day' + CASE 
							WHEN LeaveDay = 0.5 THEN ' (Half day)'
							ELSE ''
							END
					ELSE '' END
					) + (CASE 
					WHEN ISNULL(T.IsHoliday, 0) = 0
						AND isOffday = 1
						AND (ShiftId IS NULL OR ShiftId = -1) THEN (CASE 
							WHEN od.EmpId IS NULL THEN ', Off day'
							ELSE ', Off day no match' END
							)
					ELSE '' END
					) + (CASE 
					WHEN ISNULL(T.IsHoliday, 0) = 0
						AND isOffday = 1
						AND ShiftId IS NOT NULL
						AND ShiftId != -1
						AND od.EmpId IS NOT NULL THEN ', Off day no match'
					ELSE '' END
					) + (CASE 
					WHEN ISNULL(T.IsHoliday, 0) = 1
						AND ShiftId IS NULL THEN ', PH'
					ELSE '' END
					) + (CASE 
					WHEN isNotWork = 1
						AND T.LeaveTypeId IS NULL THEN ', Absent'
					ELSE (
							(CASE 
								WHEN lv.[Name] IS NULL THEN ''
								ELSE ', ' + lv.[Name] + (CASE 
										WHEN lv2.[Name] IS NULL THEN ''
										ELSE ' & ' + lv2.[Name] END
										) + (CASE 
										WHEN LeaveDay = 0.5 THEN ' (Half day)'
										ELSE '' END
										) END
								) + CASE 
							WHEN LeaveDay = 0.5
								AND isNotWork = 1 THEN ', Absent'
							ELSE '' END
							) END
					), 1, 2, ''), CASE 
				WHEN AttendanceDate1 IS NULL THEN 'No Data'
				ELSE NULL
				END) AS Notes
		,T.SectionCode
		,T.DepartmentCode
	FROM (
		SELECT e.Code
			,e.EmpId
			,FullName
			,NickName
			,g.[Name] [Team]
			,g.Code [TeamCode]
			,g.[Rank]
			,c.WorkDate AS AttendanceDate
			,a.AttendanceDate AS AttendanceDate1
			,c.ShiftId
			,s.code AS ShiftCode
			,s.BeginCheckInTime AS ExpectedInTime
			,s.BeginCheckOutTime AS ExpectedOutTime
			,a.InFixed
			,a.OutFixed
			,a.LateIn
			,a.EarlyOut
			,TotalWorkHours
			,c.IsKeepInView
			,c.LeaveDay
			,ISNULL(a.LeaveTypeId, c.LeaveTypeId) AS LeaveTypeId
			,ISNULL(a.LeaveTypeId2, c.LeaveTypeId2) AS LeaveTypeId2
			,Absence
			,(CASE 
				WHEN isnull(a.Absence, 0) = 0
					AND isnull(a.LateIn, 0) > 0 THEN 1
				ELSE 0 END
				) AS isLateIn
			,(CASE 
				WHEN isnull(a.Absence, 0) = 0
					AND isnull(a.EarlyOut, 0) > 15 THEN 1
				ELSE 0 END
				) AS isEarlyOut
			,(CASE 
				WHEN (
						isnull(a.Absence, 0) = 0
						AND a.InFixed IS NULL
						AND @now > (
							(CASE 
								WHEN s.IsInAfterDay = 1 THEN DATEADD(DD, 1, a.AttendanceDate)
								ELSE a.AttendanceDate END
								) + ' ' + s.EndCheckInTime
							)
						) THEN 1
				ELSE 0 END
				) AS isMissingCheckin
			,(CASE 
				WHEN (
						isnull(a.Absence, 0) = 0
						AND a.OutFixed IS NULL
						AND @now > (
							(CASE 
								WHEN s.IsOutAfterDay = 1 THEN DATEADD(DD, 1, a.AttendanceDate)
								ELSE a.AttendanceDate END
								) + ' ' + s.EndCheckOutTime
							)
						) THEN 1
				ELSE 0 END
				) AS isMissingCheckOut
			,(CASE 
				WHEN (
						a.ShiftId IS NOT NULL
						AND a.InFixed IS NULL
						AND a.OutFixed IS NULL
						AND a.TotalWorkHours IS NULL
						AND @now > (
							(CASE 
								WHEN s.IsInAfterDay = 1 THEN DATEADD(DD, 1, a.AttendanceDate)
								ELSE a.AttendanceDate END
								) + ' ' + s.EndCheckInTime
							)
						) THEN 1
				ELSE 0 END
				) AS isNotWork
			,c.isOffday
			,CONVERT(BIT, CASE 
					WHEN ot.EmpId IS NULL THEN 0
					ELSE 1
					END) IsOvertime
			,(ISNULL(ot.NormalHours, 0) + ISNULL(ot.OffHours, 0) + ISNULL(ot.PublicHours, 0) + ISNULL(ot.SpecialHours, 0)) OvertimeHours
			,ot.[Status] AS OvertimeStatus
			,c.IsHoliday
			,(CASE 
				WHEN ISNULL(s_CrossDay.IsOutAfterDay, 0) = 1 THEN 1
				ELSE 0 END
				) AS IsShiftCrossDay
			,sec.Code AS SectionCode
			,de.Code AS DepartmentCode
		FROM dbo.Employee AS e WITH (NOLOCK)
			INNER JOIN dbo.tmpEmployeeCalendar AS c WITH (NOLOCK) ON c.EmpId = e.EmpId
			AND c.WorkDate BETWEEN @fromtime
				AND @totime
			INNER JOIN #tmpEmployee AS tblemp ON e.EmpId = tblemp.EmpId
			LEFT JOIN dbo.EmployeeSummary AS e_s WITH (NOLOCK) ON e_s.EmpId = e.EmpId
			LEFT JOIN dbo.EmployeeCalendar AS c_CrossDay WITH (NOLOCK) ON c_CrossDay.WorkDate = DATEADD(D, - 1, c.WorkDate)
			AND c_CrossDay.EmpId = e.EmpId
			LEFT JOIN dbo.[Shift] AS s_CrossDay WITH (NOLOCK) ON s_CrossDay.ShiftId = c_CrossDay.ShiftId
			LEFT JOIN dbo.EmployeeCalendar AS c_CurDay WITH (NOLOCK) ON c_CurDay.WorkDate = DATEADD(D, - 1, c.WorkDate)
			AND c_CurDay.EmpId = e.EmpId
			LEFT JOIN dbo.[Shift] AS s_CurDay WITH (NOLOCK) ON s_CurDay.ShiftId = c_CurDay.ShiftId
			AND (
				(
					s_CrossDay.IsInAfterDay = 0
					OR @isRealDate = 0
					)
				OR (
					(
						s_CrossDay.IsInAfterDay = 1
						OR s_CurDay.IsInAfterDay = 1
						)
					AND @isRealDate = 1
					AND c.WorkDate = c_CrossDay.WorkDate
					)
				)
			LEFT JOIN dbo.[Shift] AS s WITH (NOLOCK) ON s.ShiftId = c.ShiftId
			LEFT JOIN dbo.EmployeeAttendance AS a WITH (NOLOCK) ON a.AttendanceDate = c.WorkDate
			AND a.empid = e.empid
			LEFT JOIN dbo.[Group] AS g WITH (NOLOCK) ON e.groupid = g.groupid
			INNER JOIN dbo.[Section] AS sec WITH (NOLOCK) ON sec.SectionId = g.SectionId
			INNER JOIN dbo.[Department] AS de WITH (NOLOCK) ON de.DepartmentId = sec.DepartmentId
			INNER JOIN #tmpGroup AS tmpgr ON g.GroupId = tmpgr.GroupId
			LEFT JOIN dbo.OTDailyRequest AS ot WITH (NOLOCK) ON a.attendancedate = ot.OvertimeDate
			AND a.EmpId = ot.EmpId
		WHERE @isLocal IS NULL
			OR e_s.IsLocal = @isLocal
		) AS T
		LEFT JOIN dbo.LeaveType AS lv WITH (NOLOCK) ON lv.LeaveTypeId = T.LeaveTypeId
		LEFT JOIN dbo.LeaveType AS lv2 WITH (NOLOCK) ON lv2.LeaveTypeId = T.LeaveTypeId2
		LEFT JOIN @OutOffDay AS od ON t.AttendanceDate = od.WorkDate
		AND t.EmpId = od.EmpId
	WHERE @type = 0
		OR (
			@type = 1
			AND ISNULL(T.isMissingCheckin, 1) = 1
			)
		OR (
			@type = 2
			AND T.isMissingCheckout = 1
			)
		OR (
			@type = 3
			AND T.isLateIn = 1
			)
		OR (
			@type = 4
			AND T.isEarlyOut = 1
			)
		OR (
			@type = 5
			AND T.isNotWork = 1
			)
	ORDER BY attendancedate DESC
		,[Rank]
		,TeamCode
		,T.code

	SELECT c.WorkDate
		,rd.EmpId
		,rd.RequestDate
		,rd.FromDate
		,rd.ToDate
		,rd.FromTime
		,rd.ToTime
		,rd.TotalDays
		,rd.CurrentStatus
		,rd.KeepInViewTypeId
		,rd.Remark
		,rd.CreatedDate
		,(CASE 
			WHEN rd.RequestType = 5
				OR rd.RequestType = 7 THEN (CASE 
					WHEN s1.ShiftID IS NULL THEN 'OFF'
					ELSE s1.[Name] END
					)
			ELSE s3.[Name] END
			) AS FromShift
		,(CASE 
			WHEN s2.ShiftID IS NULL THEN 'OFF'
			ELSE s2.[Name] END
			) AS ToShift
		,rd.InOutMins AS TotalMins
		,rd.RequestType
		,rd.LeaveTypeId
		,l.[Name] AS LeaveTypeName
	FROM #tmpDailyRequest AS rd WITH (NOLOCK)
		INNER JOIN dbo.tmpEmployeeCalendar AS c WITH (NOLOCK) ON (
			(
				rd.WorkDate IS NOT NULL AND rd.WorkDate = c.WorkDate) 
				OR (rd.WorkDate IS NULL AND c.WorkDate BETWEEN CAST(rd.FromDate AS DATE) AND CAST(rd.ToDate AS DATE))
			)
		AND c.EmpId = rd.EmpId
		AND (
			(
				rd.RequestType = @LeaveRequestTypeId
				--AND rd.RequestId = c.RequestId
				AND c.IsHoliday = 0
				AND c.IsOffDay = 0
				--AND c.IsKeepInView = 0
				)
			OR rd.RequestType <> @LeaveRequestTypeId
			)
		LEFT JOIN dbo.LeaveType AS l WITH (NOLOCK) ON l.LeaveTypeId = rd.LeaveTypeId
		LEFT JOIN dbo.[Shift] AS s1 WITH (NOLOCK) ON s1.ShiftId = rd.FromShift
		LEFT JOIN dbo.[Shift] AS s2 WITH (NOLOCK) ON s2.ShiftId = rd.ToShift
		LEFT JOIN dbo.[Shift] AS s3 WITH (NOLOCK) ON s3.ShiftId = c.ShiftId

	DROP TABLE #tmpGroup

	DROP TABLE #tmpEmployee

	DROP TABLE #tmpDailyRequest
END
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAttendance_ProcessingAndInsert]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EmployeeAttendance_ProcessingAndInsert] @empId INT = NULL
	,@fromTime DATETIME
	,@toTime DATETIME
	,@onlyUpdate BIT = 0
AS
BEGIN
	SET XACT_ABORT ON;

	DECLARE @i INT
		,@TempEmpId INT
		,@tempFromDate DATE = @fromTime
		,@tempToDate DATE = @toTime
		,@today DATE = GETDATE()
	DECLARE @tblDateRange TABLE (WorkDate DATE)
	DECLARE @tblEmployee TABLE (
		Id INT PRIMARY KEY IDENTITY(1, 1)
		,EmpId INT
		)

	IF @tempToDate > @today
	BEGIN
		SET @tempToDate = @today
	END

	WHILE @tempFromDate <= @tempToDate
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM @tblDateRange
				WHERE WorkDate = @tempFromDate
				)
		BEGIN
			INSERT INTO @tblDateRange (WorkDate)
			VALUES (@tempFromDate)
		END

		SET @tempFromDate = DATEADD(DAY, 1, @tempFromDate)
	END

	IF EXISTS (
			SELECT EmpId
			FROM dbo.EmployeeCalendar AS empca WITH (NOLOCK)
				LEFT JOIN @tblDateRange AS tbldate ON empca.WorkDate = tbldate.WorkDate
			WHERE (
					@empId IS NULL
					OR EmpId = @empId
					)
				AND tbldate.WorkDate IS NULL
			)
	BEGIN
		DECLARE @ErrCode INT = 0
			,@ErrMsg VARCHAR(200) = ''

		EXEC dbo.EmployeeCalendar_Insert @EmpId = @empId
			,@fromdate = @fromTime
			,@todate = @tempToDate
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END

	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#TimeRecord'
			)
	BEGIN
		DROP TABLE #TimeRecord
	END

	CREATE TABLE #TimeRecord (
		Id INT
		,EmpId INT
		,RecordTime DATETIME
		,InOutType TINYINT
		)

	-- Get all in/out data into temp table to calculate
	INSERT INTO #TimeRecord (
		Id
		,EmpId
		,RecordTime
		,InOutType
		)
	SELECT tr.Id
		,tr.EmpId
		,tr.RecordTime
		,tr.InOutType
	FROM dbo.TimeRecord AS tr WITH (NOLOCK)
		INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON tr.EmpId = emp.EmpId
	WHERE emp.[Enabled] = 1
		AND emp.isDeleted = 0
		AND tr.RecordTime BETWEEN DATEADD(HH, - 2, CONVERT(VARCHAR(10), @fromTime, 111))
			AND DATEADD(d, 2, CONVERT(VARCHAR(10), @toTime, 111))
		AND emp.JoinedDate <= CAST(tr.RecordTime AS DATE)
		AND (
			@empId IS NULL
			OR tr.EmpId = @empId
			)

	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#LeaveRequestHalfDay'
			)
	BEGIN
		DROP TABLE #LeaveRequestHalfDay
	END

	CREATE TABLE #LeaveRequestHalfDay (
		EmpId INT
		,OnDate DATETIME
		,FromTime DATETIME
		,ToTime DATETIME
		)

	-- Get all leave request half day
	INSERT INTO #LeaveRequestHalfDay (
		EmpId
		,OnDate
		,FromTime
		,ToTime
		)
	SELECT lv.EmpId
		,lv.OnDate
		,FromTime
		,ToTime
	FROM dbo.LeaveRequestDetail AS lv WITH (NOLOCK)
		INNER JOIN (
		SELECT ldt.empId
			,OnDate
		FROM dbo.LeaveRequestDetail AS ldt WITH (NOLOCK)
			INNER JOIN dbo.WorkingTimeRequest AS wrq WITH (NOLOCK) ON ldt.RequestId = wrq.RequestId
		WHERE WorkType = 2
			AND IsHalfDay = 1 -- 2: leave, 1: Half day
			AND OnDate BETWEEN CONVERT(VARCHAR(10), @fromTime, 111)
				AND CONVERT(VARCHAR(10), DATEADD(d, 2, @toTime), 111)
			AND (
				@empId IS NULL
				OR ldt.EmpId = @empId
				)
			AND wrq.CurrentStatus IN (4, 6)
		GROUP BY ldt.empId
			,OnDate
		HAVING COUNT(*) = 1
		) a ON (
			a.EmpId = lv.EmpId
			AND a.OnDate = lv.OnDate
			)
		INNER JOIN dbo.WorkingTimeRequest AS rq WITH (NOLOCK) ON lv.RequestId = rq.RequestId
	WHERE lv.IsHalfDay = 1
		AND (
			@empId IS NULL
			OR lv.EmpId = @empId
			)
		AND rq.CurrentStatus IN (4, 6)

	-- Get all calendars of employees into temp table
	IF EXISTS (
			SELECT *
			FROM INFORMATION_SCHEMA.TABLES
			WHERE TABLE_NAME = '#EmpCalendar'
			)
	BEGIN
		DROP TABLE #EmpCalendar
	END

	CREATE TABLE #EmpCalendar (
		Id INT PRIMARY KEY IDENTITY(1, 1)
		,EmpId INT
		,WorkDate DATETIME
		,ShiftId INT
		,IsHoliday BIT
		,IsOffDay BIT
		,IsLeaveDay BIT
		,LeaveTypeId INT NULL
		,IsKeepInView BIT
		,LateIn INT
		,EarlyOut INT
		,RequestedCheckInTime DATETIME
		,RequestedCheckOutTime DATETIME
		,BeginCheckInTime DATETIME
		,EndCheckInTime DATETIME
		,BeginCheckOutTime DATETIME
		,EndCheckOutTime DATETIME
		,BreakTimeMins INT
		,LeaveDay DECIMAL(18, 1)
		)

	INSERT INTO #EmpCalendar (
		EmpId
		,WorkDate
		,ShiftId
		,IsHoliday
		,IsOffDay
		,IsLeaveDay
		,LeaveTypeId
		,IsKeepInView
		,LateIn
		,EarlyOut
		,RequestedCheckInTime
		,RequestedCheckOutTime
		,BeginCheckInTime
		,EndCheckInTime
		,BeginCheckOutTime
		,EndCheckOutTime
		,BreakTimeMins
		,LeaveDay
		)
	SELECT ec.EmpId
		,ec.WorkDate
		,ec.ShiftId
		,ec.IsHoliday
		,ec.IsOffDay
		,ec.IsLeaveDay
		,ec.LeaveTypeId
		,ec.IsKeepInView
		,ec.LateIn
		,ec.EarlyOut
		,ec.RequestedCheckinTime
		,ec.RequestedCheckoutTime
		,CASE 
			WHEN IsInAfterDay = 1 THEN DATEADD(d, 1, WorkDate + ' ' + s.EndCheckInTime)
			ELSE CAST(WorkDate + ' ' + s.EndCheckInTime AS DATETIME)
			END AS BeginCheckInTime
		,CASE 
			WHEN IsInAfterDay = 1 THEN DATEADD(d, 1, WorkDate + ' ' + s.EndCheckInTime)
			ELSE CAST(WorkDate + ' ' + s.EndCheckInTime AS DATETIME)
			END AS EndCheckInTime
		,CASE 
			WHEN IsOutAfterDay = 1 THEN DATEADD(d, 1, WorkDate + ' ' + s.BeginCheckOutTime)
			ELSE CAST(WorkDate + ' ' + s.BeginCheckOutTime AS DATETIME)
			END AS BeginCheckOutTime
		,CASE 
			WHEN IsOutAfterDay = 1 THEN DATEADD(d, 1, WorkDate + ' ' + s.EndCheckOutTime)
			ELSE CAST(WorkDate + ' ' + s.EndCheckOutTime AS DATETIME)
			END AS EndCheckOutTime
		,BreakTimeMins
		,LeaveDay
	FROM dbo.EmployeeCalendar AS ec WITH (NOLOCK)
		LEFT JOIN dbo.Shift AS s WITH (NOLOCK) ON s.ShiftId = ec.ShiftId
	WHERE (
			@EmpId IS NULL
			OR ec.EmpId = @EmpId
			)
		AND ec.WorkDate BETWEEN @FromTime
			AND @ToTime
	ORDER BY ec.EmpId
		,ec.WorkDate

	IF @empId IS NULL
	BEGIN
		-- Get all enable staff to calculate 
		INSERT INTO @tblEmployee (EmpId)
		SELECT e.EmpId
		FROM dbo.Employee AS e WITH (NOLOCK)
		WHERE isDeleted IS NULL
			OR isDeleted = 0
			AND EXISTS (
				SELECT 1
				FROM dbo.EmployeeCalendar AS cl WITH (NOLOCK)
				WHERE (
						ISNULL(cl.LeaveDay, 0) <> 0
						OR cl.ShiftId IS NULL
						)
					AND DATEDIFF(DD, @fromTime, cl.WorkDate) >= 0
					AND DATEDIFF(DD, WorkDate, @toTime) >= 0
					AND e.EmpId = cl.EmpId
				)

		SET @i = 1

		WHILE EXISTS (
				SELECT 1
				FROM @tblEmployee
				WHERE Id = @i
				)
		BEGIN
			SELECT @TempEmpId = EmpId
			FROM @tblEmployee
			WHERE Id = @i

			EXEC dbo.EmployeeAttendance_ProcessingAndInsert_ForEmpId @TempEmpId
				,@fromTime
				,@toTime
				,@onlyUpdate

			SET @i = @i + 1
		END

		EXEC dbo.EmployeeAttendance_ProcessingAndInsert_ForWorkDay @empId
			,@fromTime
			,@toTime
	END
	ELSE
	BEGIN
		EXEC dbo.EmployeeAttendance_ProcessingAndInsert_ForEmpId @EmpId
			,@fromTime
			,@toTime
			,@onlyUpdate
	END

	EXEC dbo.Discipline_Insert @fromTime
		,@toTime
		,@EmpId

	DROP TABLE #TimeRecord

	DROP TABLE #EmpCalendar

	DROP TABLE #LeaveRequestHalfDay
END
GO
/****** Object:  StoredProcedure [dbo].[EmployeeAttendance_ProcessingAndInsert_ForEmpId]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[EmployeeAttendance_ProcessingAndInsert_ForEmpId] @empId INT
	,@fromTime DATETIME
	,@toTime DATETIME
	,@onlyUpdate BIT = 0
AS
BEGIN
	SET XACT_ABORT ON;
	
	DECLARE @RangeToScanTime SMALLINT = 480 -- 480 munites
		,@DateChangeRuleLateInEarlyOutRequest DATETIME = '2015-10-19'
	DECLARE @TimeRecord TABLE (
		Id INT
		,EmpId INT
		,RecordTime DATETIME
		,InOutType TINYINT
		)

	INSERT INTO @TimeRecord (
		Id
		,EmpId
		,RecordTime
		,InOutType
		)
	SELECT Id
		,EmpId
		,RecordTime
		,InOutType
	FROM #TimeRecord
	WHERE RecordTime BETWEEN DATEADD(HH, - 2, CONVERT(VARCHAR(10), @fromTime, 111))
			AND DATEADD(d, 2, CONVERT(VARCHAR(10), @toTime, 111))
		AND EmpId = @empId

	DECLARE @i INT
		,@attendaceDate DATETIME
	DECLARE @WorkDate DATETIME
		,@ShiftId INT
		,@IsHoliday BIT
		,@isOffDay BIT
		,@IsLeaveDay BIT
		,@LeaveTypeId INT
		,@LateIn INT
		,@EarlyOut INT
		,@RequestedCheckinTime DATETIME
		,@RequestedCheckoutTime DATETIME
		,@BeginCheckInTime DATETIME
		,@EndCheckInTime DATETIME
		,@BeginCheckOutTime DATETIME
		,@EndCheckOutTime DATETIME
		,@InOfMachine DATETIME
		,@OutOfMachine DATETIME
		,@ExpectedInTime DATETIME
		,@ExpectedOutTime DATETIME
		,@Absence BIT
		,@IsRightShift BIT
		,@ActualLateIn INT
		,@ActualEarlyOut INT
		,@TotalWorkHours DECIMAL(18, 2)
		,@BreakTimeMins INT
		,@LeaveDay DECIMAL(18, 1)
		,@Notes NVARCHAR(2000)
		,@RequestLeaveTimeBegin DATETIME
		,@RequestLeaveTimeEnd DATETIME
		,@adjustLateIn INT
		,@adjustEarlyOut INT

	SET @i = 0
	SET @attendaceDate = CONVERT(VARCHAR(10), @fromTime, 111)

	WHILE DATEDIFF(d, @attendaceDate, @toTime) >= 0
	BEGIN
		SELECT @Absence = 0
			,@InOfMachine = NULL
			,@OutOfMachine = NULL
			,@ExpectedOutTime = NULL
			,@IsRightShift = NULL
			,@ExpectedInTime = NULL
			,@ExpectedOutTime = NULL
			,@ActualLateIn = 0
			,@ActualEarlyOut = 0
			,@RequestedCheckinTime = NULL
			,@RequestedCheckoutTime = NULL
			,@TotalWorkHours = NULL
			,@BreakTimeMins = 0
			,@ShiftId = NULL
			,@LeaveTypeId = NULL
			,@RequestLeaveTimeBegin = NULL
			,@RequestLeaveTimeEnd = NULL
			,@adjustLateIn = 0
			,@adjustEarlyOut = 0

		SELECT @WorkDate = WorkDate
			,@ShiftId = ShiftId
			,@IsHoliday = IsHoliday
			,@isOffDay = IsOffDay
			,@IsLeaveDay = IsLeaveDay
			,@LeaveTypeId = LeaveTypeId
			,@LateIn = ISNULL(LateIn, 0)
			,@EarlyOut = ISNULL(EarlyOut, 0)
			,@RequestedCheckinTime = RequestedCheckinTime
			,@RequestedCheckoutTime = RequestedCheckoutTime
			,@BeginCheckInTime = BeginCheckInTime
			,@EndCheckInTime = EndCheckInTime
			,@BeginCheckOutTime = BeginCheckOutTime
			,@EndCheckOutTime = EndCheckOutTime
			,@BreakTimeMins = BreakTimeMins
			,@LeaveDay = LeaveDay
		FROM #EmpCalendar
		WHERE EmpId = @empId
			AND WorkDate = @attendaceDate

		IF DATEDIFF(D, @DateChangeRuleLateInEarlyOutRequest, @WorkDate) >= 0
		BEGIN
			SELECT @LateIn = 0
				,@EarlyOut = 0
		END

		-- If Has Shift
		IF @ShiftId IS NOT NULL
			AND ISNULL(@LeaveDay, 0) <> 1
		BEGIN
			SET @ExpectedInTime = @BeginCheckInTime
			SET @ExpectedOutTime = @BeginCheckOutTime

			-- get time in
			SELECT @InOfMachine = MIN(RecordTime)
			FROM @TimeRecord
			WHERE InOutType = 0
				AND RecordTime BETWEEN DATEADD(mi, - @RangeToScanTime, @ExpectedInTime)
					AND @ExpectedOutTime

			-- get time out
			SELECT @OutOfMachine = MAX(RecordTime)
			FROM @TimeRecord
			WHERE InOutType = 1
				AND RecordTime BETWEEN @ExpectedInTime
					AND DATEADD(mi, @RangeToScanTime, @ExpectedOutTime)

			IF @InOfMachine > @OutOfMachine
			BEGIN
				SET @OutOfMachine = NULL
			END

			IF @RequestedCheckinTime IS NOT NULL
			BEGIN
				SET @InOfMachine = @RequestedCheckinTime
			END

			IF @RequestedCheckoutTime IS NOT NULL
			BEGIN
				SET @OutOfMachine = @RequestedCheckoutTime
			END

			IF DATEADD(mi, @EarlyOut, @OutOfMachine) < @ExpectedOutTime
			BEGIN
				SET @ActualEarlyOut = DATEDIFF(MINUTE, DATEADD(mi, @EarlyOut, @OutOfMachine), @ExpectedOutTime)
			END

			IF DATEADD(mi, - @LateIn, @InOfMachine) > @ExpectedINTime
			BEGIN
				SET @ActualLateIn = DATEDIFF(MINUTE, @ExpectedINTime, DATEADD(mi, - @LateIn, @InOfMachine))
			END

			IF @InOfMachine IS NOT NULL
			BEGIN
				IF @InOfMachine < @ExpectedInTime
				BEGIN
					SET @TotalWorkHours = (DATEDIFF(mi, @ExpectedInTime, @OutOfMachine) - ISNULL(@BreakTimeMins, 0)) / 60.0
				END
				ELSE
				BEGIN
					SET @TotalWorkHours = (DATEDIFF(mi, @InOfMachine, @OutOfMachine) - ISNULL(@BreakTimeMins, 0)) / 60.0
				END

				-- half leave
				IF @IsLeaveDay = 1
					AND @LeaveDay = 0.5
				BEGIN
					SELECT @RequestLeaveTimeBegin = FromTime
						,@RequestLeaveTimeEnd = ToTime
					FROM #LeaveRequestHalfDay
					WHERE EmpId = @empId
						AND OnDate = @attendaceDate

					IF @RequestLeaveTimeBegin IS NOT NULL
						AND @RequestLeaveTimeEnd IS NOT NULL
					BEGIN
						IF DATEDIFF(mi, @ExpectedInTime, @RequestLeaveTimeBegin) < 30
							AND DATEDIFF(mi, @ExpectedInTime, @RequestLeaveTimeBegin) > - 30
						BEGIN
							SET @adjustLateIn = DATEDIFF(mi, @RequestLeaveTimeBegin, @RequestLeaveTimeEnd)
							SET @ActualLateIn = @ActualLateIn - @adjustLateIn

							IF @ActualLateIn < 0
							BEGIN
								SET @ActualLateIn = 0
							END
						END
						ELSE IF DATEDIFF(mi, @ExpectedOutTime, @RequestLeaveTimeEnd) < 30
							AND DATEDIFF(mi, @ExpectedOutTime, @RequestLeaveTimeEnd) > - 30
						BEGIN
							SET @adjustEarlyOut = DATEDIFF(mi, @RequestLeaveTimeBegin, @RequestLeaveTimeEnd)
							SET @ActualEarlyOut = @ActualEarlyOut - @adjustEarlyOut

							IF @ActualEarlyOut < 0
							BEGIN
								SET @ActualEarlyOut = 0
							END
						END
					END
				END
			END
		END
		ELSE IF ISNULL(@isOffDay, 0) = 0
			AND ISNULL(@IsHoliday, 0) = 0
			AND ISNULL(@LeaveDay, 0) <> 1
		BEGIN
			-- get time in
			SELECT @InOfMachine = MIN(RecordTime)
			FROM @TimeRecord
			WHERE InOutType = 0
				AND RecordTime BETWEEN DATEADD(mi, 270, @attendaceDate)
					AND DATEADD(mi, 270, DATEADD(d, 1, @attendaceDate)) -- 4h30 of after day

			-- get time out
			SELECT @OutOfMachine = MAX(RecordTime)
			FROM @TimeRecord
			WHERE InOutType = 1
				AND RecordTime BETWEEN DATEADD(mi, 540, @attendaceDate)
					AND DATEADD(mi, 720, DATEADD(d, 1, @attendaceDate)) -- 12h of after day

			IF @InOfMachine > @OutOfMachine
			BEGIN
				SET @OutOfMachine = NULL
			END

			IF @RequestedCheckinTime IS NOT NULL
			BEGIN
				SET @InOfMachine = @RequestedCheckinTime
			END

			IF @RequestedCheckoutTime IS NOT NULL
			BEGIN
				SET @OutOfMachine = @RequestedCheckoutTime
			END

			IF @InOfMachine IS NOT NULL
				AND @OutOfMachine IS NOT NULL
			BEGIN
				SET @TotalWorkHours = (DATEDIFF(mi, @InOfMachine, @OutOfMachine)) / 60.0
			END
		END

		IF @ShiftId IS NULL
			OR (
				@IsLeaveDay = 1
				AND @LeaveDay = 1
				)
		BEGIN
			SET @Absence = 1
		END
		ELSE IF @InOfMachine IS NULL
			AND @OutOfMachine IS NULL
		BEGIN
			SET @Absence = 1
		END

		--SELECT @ShiftId, @InOfMachine, @OutOfMachine, @IsLeaveDay, @isOffDay, @IsHoliday
		IF DATEDIFF(DD, @attendaceDate, GETDATE()) >= 0
		BEGIN
			IF (
					@ShiftId IS NOT NULL
					OR @InOfMachine IS NOT NULL
					OR @OutOfMachine IS NOT NULL
					OR @IsLeaveDay = 1
					OR @isOffDay = 1
					OR @IsHoliday = 1
					)
			BEGIN
				-- insert or update
				IF EXISTS (
						SELECT 1
						FROM dbo.EmployeeAttendance WITH (NOLOCK)
						WHERE EmpId = @empId
							AND DATEDIFF(d, AttendanceDate, @attendaceDate) = 0
						)
				BEGIN
					--update
					UPDATE dbo.EmployeeAttendance
					SET ShiftId = @ShiftId
						,InFixed = @InOfMachine
						,OutFixed = @OutOfMachine
						,ExpectedInTime = @ExpectedInTime
						,ExpectedOutTime = @ExpectedOutTime
						,LateIn = @ActualLateIn
						,EarlyOut = @ActualEarlyOut
						,LeaveTypeId = @LeaveTypeId
						,Absence = @Absence
						,TotalWorkHours = @TotalWorkHours
						,IsRightShift = @IsRightShift
						,LeaveDay = @LeaveDay
						,InsertDate = GETDATE()
					WHERE EmpId = @empId
						AND DATEDIFF(d, AttendanceDate, @attendaceDate) = 0
				END
				ELSE
				BEGIN
					--insert
					INSERT INTO dbo.EmployeeAttendance (
						EmpId
						,AttendanceDate
						,ShiftId
						,InFixed
						,OutFixed
						,ExpectedInTime
						,ExpectedOutTime
						,LateIn
						,EarlyOut
						,LeaveTypeId
						,Absence
						,TotalWorkHours
						,IsRightShift
						,LeaveDay
						,InsertDate
						)
					VALUES (
						@empId
						,@attendaceDate
						,@ShiftId
						,@InOfMachine
						,@OutOfMachine
						,@ExpectedInTime
						,@ExpectedOutTime
						,@ActualLateIn
						,@ActualEarlyOut
						,@LeaveTypeId
						,@Absence
						,@TotalWorkHours
						,@IsRightShift
						,@LeaveDay
						,GETDATE()
						)
				END
			END
			ELSE
			BEGIN
				DELETE
				FROM dbo.EmployeeAttendance
				WHERE EmpId = @empId
					AND DATEDIFF(d, AttendanceDate, @attendaceDate) = 0
			END
		END

		SET @i = @i + 1
		SET @attendaceDate = DATEADD(d, @i, @fromTime)
	END
END





GO
/****** Object:  StoredProcedure [dbo].[EmployeeAttendance_ProcessingAndInsert_ForWorkDay]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[EmployeeAttendance_ProcessingAndInsert_ForWorkDay] @empId INT = NULL
	,@fromTime DATETIME
	,@toTime DATETIME
AS
BEGIN
	UPDATE att
	SET att.ShiftId = c.ShiftID
		,att.InFixed = c.CheckIn
		,att.OutFixed = c.CheckOut
		,att.ExpectedInTime = c.ExpectedInTime
		,att.ExpectedOutTime = c.ExpectedOutTime
		,att.LateIn = CASE 
			WHEN c.LateIn <= 0 THEN 0
			ELSE c.LateIn
			END
		,att.EarlyOut = CASE 
			WHEN c.EarlyOut <= 0 THEN 0
			ELSE c.EarlyOut
			END
		,att.LeaveTypeId = NULL
		,att.Absence = c.Absence
		,att.TotalWorkHours = CASE 
			WHEN c.IsValid = 1 THEN (CASE 
					WHEN c.CheckIn < c.ExpectedInTime THEN ((DATEDIFF(mi, c.ExpectedInTime, c.CheckOut) - ISNULL(c.BreakTimeMins, 0)) / 60.0)
					ELSE (DATEDIFF(mi, c.CheckIn, c.CheckOut) - ISNULL(c.BreakTimeMins, 0)) / 60.0 END
					)
			ELSE NULL
			END
		,att.LeaveDay = NULL
		,att.InsertDate = GETDATE()
		,att.LeaveTypeId2 = NULL
	FROM (
		SELECT b.EmpId
			,b.WorkDate
			,b.Code
			,b.ShiftID
			,b.CheckIn
			,b.CheckOut
			,CASE 
				WHEN (
						b.CheckIn IS NOT NULL
						AND b.CheckOut IS NOT NULL
						AND b.CheckIn < b.CheckOut
						) THEN 1
				ELSE 0
				END AS IsValid
			,CASE 
				WHEN b.CheckIn IS NULL THEN 0
				ELSE DATEDIFF(MINUTE, b.ExpectedInTime, b.CheckIn)
				END AS LateIn
			,CASE 
				WHEN b.CheckOut IS NULL THEN 0
				ELSE DATEDIFF(MINUTE, b.CheckOut, b.ExpectedOutTime)
				END AS EarlyOut
			,b.ExpectedInTime
			,b.ExpectedOutTime
			,b.BreakTimeMins
			,b.Absence
		FROM (
			SELECT a.EmpId
				,a.WorkDate
				,a.Code
				,a.ShiftID
				,(CASE 
					WHEN a.RequestedCheckinTime IS NULL THEN a.CheckIn
					ELSE a.RequestedCheckinTime END
					) CheckIn
				,(CASE 
					WHEN a.RequestedCheckoutTime IS NULL THEN a.CheckOut
					ELSE a.RequestedCheckoutTime END
					) CheckOut
				,a.ExpectedInTime
				,a.ExpectedOutTime
				,a.BreakTimeMins
				,CASE 
					WHEN (
							a.IsOffDay = 1
							OR a.IsHoliday = 1
							OR (
								a.IsLeaveDay = 1
								AND a.LeaveDay = 1
								)
							OR (
								a.CheckIn IS NULL
								AND a.CheckOut IS NULL
								)
							) THEN 1
					ELSE 0
					END AS Absence
			FROM (
				SELECT cl.EmpId
					,cl.WorkDate
					,sh.ShiftID
					,sh.Code
					,sh.BeginCheckInTime
					,sh.BeginCheckOutTime
					,sh.IsInAfterDay
					,sh.IsOutAfterDay
					,cl.RequestedCheckinTime
					,cl.RequestedCheckoutTime
					,cl.LateIn
					,cl.EarlyOut
					,cl.IsHoliday
					,cl.IsOffDay
					,cl.IsLeaveDay
					,cl.LeaveTypeId
					,cl.IsKeepInView
					,cl.LeaveDay
					,sh.BreakTimeMins
					,CASE 
						WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
						ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111)
						END + ' ' + sh.BeginCheckInTime AS ExpectedInTime
					,CASE 
						WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
						ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111)
						END + ' ' + sh.BeginCheckOutTime AS ExpectedOutTime
					,(
						SELECT MIN(RecordTime)
						FROM dbo.TimeRecord WITH (NOLOCK)
						WHERE InOutType = 0
							AND EmpID = cl.EmpId
							AND RecordTime BETWEEN DATEADD(mi, - 480, (CASE 
											WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
											ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckInTime
											))
								AND (CASE 
										WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
										ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckOutTime
										)
						) AS CheckIn
					,(
						SELECT MAX(RecordTime)
						FROM dbo.TimeRecord WITH (NOLOCK)
						WHERE InOutType = 1
							AND EmpID = cl.EmpId
							AND RecordTime BETWEEN (CASE 
										WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
										ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckInTime
										)
								AND DATEADD(mi, 480, (CASE 
											WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
											ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckOutTime
											))
						) AS CheckOut
				FROM dbo.EmployeeCalendar AS cl WITH (NOLOCK)
					INNER JOIN dbo.[Shift] AS sh WITH (NOLOCK) ON cl.ShiftId = sh.ShiftID
				WHERE ISNULL(cl.LeaveDay, 0) = 0
					AND DATEDIFF(DD, @fromTime, WorkDate) >= 0
					AND DATEDIFF(DD, WorkDate, @toTime) >= 0
					AND (
						@empId IS NULL
						OR cl.EmpId = @empId
						)
				) AS a
			) AS b
		) AS c
		INNER JOIN dbo.EmployeeAttendance AS att WITH (NOLOCK) ON c.EmpId = att.EmpId
		AND c.WorkDate = att.AttendanceDate

	INSERT INTO dbo.EmployeeAttendance (
		[EmpId]
		,[AttendanceDate]
		,[ShiftId]
		,[InFixed]
		,[OutFixed]
		,[ExpectedInTime]
		,[ExpectedOutTime]
		,[LateIn]
		,[EarlyOut]
		,[Absence]
		,[TotalWorkHours]
		,[InsertDate]
		)
	SELECT c.EmpId
		,c.WorkDate
		,c.ShiftID
		,c.CheckIn
		,c.CheckOut
		,c.ExpectedInTime
		,c.ExpectedOutTime
		,CASE 
			WHEN c.LateIn <= 0 THEN 0
			ELSE c.LateIn
			END AS LateIn
		,CASE 
			WHEN c.EarlyOut <= 0 THEN 0
			ELSE c.EarlyOut
			END AS EarlyOut
		,c.Absence
		,CAST((CASE 
				WHEN c.IsValid = 1 THEN (CASE 
						WHEN c.CheckIn < c.ExpectedInTime THEN ((DATEDIFF(mi, c.ExpectedInTime, c.CheckOut) - ISNULL(c.BreakTimeMins, 0)) / 60.0)
						ELSE (DATEDIFF(mi, c.CheckIn, c.CheckOut) - ISNULL(c.BreakTimeMins, 0)) / 60.0 END
						)
				ELSE NULL END
				) AS DECIMAL(18, 2)) TotalHours
		,GETDATE()
	FROM (
		SELECT b.EmpId
			,b.WorkDate
			,b.Code
			,b.ShiftID
			,b.CheckIn
			,b.CheckOut
			,CASE 
				WHEN (
						b.CheckIn IS NOT NULL
						AND b.CheckOut IS NOT NULL
						AND b.CheckIn < b.CheckOut
						) THEN 1
				ELSE 0
				END AS IsValid
			,CASE 
				WHEN b.CheckIn IS NULL THEN 0
				ELSE DATEDIFF(MINUTE, b.ExpectedInTime, b.CheckIn)
				END AS LateIn
			,CASE 
				WHEN b.CheckOut IS NULL THEN 0
				ELSE DATEDIFF(MINUTE, b.CheckOut, b.ExpectedOutTime)
				END AS EarlyOut
			,b.ExpectedInTime
			,b.ExpectedOutTime
			,b.BreakTimeMins
			,b.Absence
		FROM (
			SELECT a.EmpId
				,a.WorkDate
				,a.Code
				,a.ShiftID
				,(CASE 
					WHEN a.RequestedCheckinTime IS NULL THEN a.CheckIn
					ELSE a.RequestedCheckinTime END
					) CheckIn
				,(CASE 
					WHEN a.RequestedCheckoutTime IS NULL THEN a.CheckOut
					ELSE a.RequestedCheckoutTime END
					) CheckOut
				,a.ExpectedInTime
				,a.ExpectedOutTime
				,a.BreakTimeMins
				,CASE 
					WHEN (
							a.IsOffDay = 1
							OR a.IsHoliday = 1
							OR (
								a.IsLeaveDay = 1
								AND a.LeaveDay = 1
								)
							OR (
								a.CheckIn IS NULL
								AND a.CheckOut IS NULL
								)
							) THEN 1
					ELSE 0
					END AS Absence
			FROM (
				SELECT cl.EmpId
					,cl.WorkDate
					,sh.ShiftID
					,sh.Code
					,sh.BeginCheckInTime
					,sh.BeginCheckOutTime
					,sh.IsInAfterDay
					,sh.IsOutAfterDay
					,cl.RequestedCheckinTime
					,cl.RequestedCheckoutTime
					,cl.LateIn
					,cl.EarlyOut
					,cl.IsHoliday
					,cl.IsOffDay
					,cl.IsLeaveDay
					,cl.LeaveTypeId
					,cl.IsKeepInView
					,cl.LeaveDay
					,sh.BreakTimeMins
					,CASE 
						WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
						ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111)
						END + ' ' + sh.BeginCheckInTime AS ExpectedInTime
					,CASE 
						WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
						ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111)
						END + ' ' + sh.BeginCheckOutTime AS ExpectedOutTime
					,(
						SELECT MIN(RecordTime)
						FROM dbo.TimeRecord WITH (NOLOCK)
						WHERE InOutType = 0
							AND EmpID = cl.EmpId
							AND RecordTime BETWEEN DATEADD(mi, - 480, (CASE 
											WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
											ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckInTime
											))
								AND (CASE 
										WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
										ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckOutTime
										)
						) AS CheckIn
					,(
						SELECT MAX(RecordTime)
						FROM dbo.TimeRecord WITH (NOLOCK)
						WHERE InOutType = 1
							AND EmpID = cl.EmpId
							AND RecordTime BETWEEN (CASE 
										WHEN sh.IsInAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
										ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckInTime
										)
								AND DATEADD(mi, 480, (CASE 
											WHEN sh.IsOutAfterDay = 0 THEN CONVERT(VARCHAR(10), cl.WorkDate, 111)
											ELSE CONVERT(VARCHAR(10), DATEADD(DD, 1, cl.WorkDate), 111) END + ' ' + sh.BeginCheckOutTime
											))
						) AS CheckOut
				FROM dbo.EmployeeCalendar AS cl WITH (NOLOCK)
					INNER JOIN dbo.[Shift] AS sh WITH (NOLOCK) ON cl.ShiftId = sh.ShiftID
				WHERE ISNULL(cl.LeaveDay, 0) = 0
					AND DATEDIFF(DD, @fromTime, WorkDate) >= 0
					AND DATEDIFF(DD, WorkDate, @toTime) >= 0
					AND (
						@empId IS NULL
						OR cl.EmpId = @empId
						)
				) AS a
			) AS b
		) AS c
		LEFT JOIN dbo.EmployeeAttendance AS att WITH (NOLOCK) ON c.EmpId = att.EmpId
		AND c.WorkDate = att.AttendanceDate
	WHERE att.EmpId IS NULL
END



