/****** Object:  StoredProcedure [dbo].[KeepInViewRequest_Reject]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[KeepInViewRequest_Reject] @RequestId BIGINT
	,@ActorId INT
	,@RoleId TINYINT
	,@Comment NVARCHAR(500) = ''
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg VARCHAR(200) = '' OUTPUT
AS
/*
Created: 20190522@Quinn.Vo
Task: reject keep in view request
DB: HRM
Original:

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @OnDate DATE
		,@EmpId INT
		,@ProcessedDate DATETIME = GETDATE()
		-- system role
		,@VerifierRoleId TINYINT = 2
		,@ApproverRoleId TINYINT = 3
		,@HRRoleId TINYINT = 6
		-- request status
		,@NotVerifiedStatusId TINYINT = 3
		,@RejectedStatusId TINYINT = 5
		,@VoidStatusId TINYINT = 7

	SELECT @OnDate = OnDate
		,@EmpId = EmpId
	FROM dbo.KeepInViewRequest WITH (NOLOCK)
	WHERE RequestId = @RequestId

	IF @RoleId = @VerifierRoleId
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @NotVerifiedStatusId
			,VerifiedStatus = @NotVerifiedStatusId
			--,VerifierId = @ActorId
			,VerifiedDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId
	END
	ELSE IF @RoleId = @ApproverRoleId
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @RejectedStatusId
			,ApprovedStatus = @NotVerifiedStatusId
			--,ApproverId = @ActorId
			,ApprovedDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId
	END
	ELSE IF @RoleId = @HRRoleId
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @VoidStatusId
			,HRStatus = @NotVerifiedStatusId
			,HRId = @ActorId
			,HRDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId

		UPDATE empca
		SET empca.IsKeepInView = 0
			,empca.ShiftId = CASE WHEN kiv.ShiftId IS NOT NULL THEN NULL ELSE empca.ShiftId END
			,empca.ModifiedBy = @ActorId
			,empca.ModifiedDate = @ProcessedDate
		FROM dbo.EmployeeCalendar AS empca WITH (ROWLOCK, UPDLOCK)
			INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON empca.WorkDate = kiv.OnDate
			AND empca.EmpId = kiv.EmpId
		WHERE kiv.RequestId = @RequestId

		EXEC dbo.KeepInViewRequest_DeleteTrans @RequestId = @RequestId

		EXEC dbo.EmployeeAttendance_ProcessingAndInsert @EmpId
			,@OnDate
			,@OnDate
			,1
	END

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @OnDate
		,@toDate = @OnDate
		,@empIds = @EmpId
		,@isUpdateRequestData = 1

	EXEC dbo.KeepInViewRequest_WriteLog @RequestId = @RequestId
		,@Comment = @Comment
END

GO
/****** Object:  StoredProcedure [dbo].[KeepInViewRequest_Reset]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[KeepInViewRequest_Reset] @RequestId BIGINT
	,@RoleId TINYINT
	,@ActorId INT
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: 20190522@Quinn.Vo
Task: reset keep in view request
DB: HRM
Original:

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @OnDate DATE
		,@EmpId INT
		,@StatusId TINYINT
		,@VerifierId INT
		,@ApproverId INT
		,@TotalMinutes INT
		,@ProcessedDate DATETIME = GETDATE()
		-- system role
		,@VerifierRoleId TINYINT = 2
		,@ApproverRoleId TINYINT = 3
		,@HRRoleId TINYINT = 6
		-- request status
		,@PendingStatusId TINYINT = 1
		,@VerifiedStatusId TINYINT = 2
		,@NotVerifiedStatusId TINYINT = 3
		,@ApprovedStatusId TINYINT = 4
		,@VoidStatusId TINYINT = 7
		,@ProcessedStatusId TINYINT = 6

	SELECT @OnDate = kiv.OnDate
		,@EmpId = r.EmpId
		,@VerifierId = r.VerifierId
		,@ApproverId = r.ApproverId
		,@StatusId = r.CurrentStatus
		,@TotalMinutes = DATEDIFF(MI, kiv.FromTime, kiv.ToTime)
	FROM dbo.KeepInViewRequest AS kiv WITH (NOLOCK)
		INNER JOIN dbo.WorkingTimeRequest AS r WITH (NOLOCK) ON kiv.RequestId = r.RequestId
		AND r.RequestId = @RequestId

	IF @RoleId = @VerifierRoleId
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @PendingStatusId
			,VerifiedStatus = @PendingStatusId
			--,VerifierId = @ActorId
			,VerifiedDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId
	END
	ELSE IF (@RoleId = @ApproverRoleId OR(@RoleId = @HRRoleId AND @ApprovedStatusId = @StatusId))
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @PendingStatusId
			,VerifiedStatus = @PendingStatusId
			,ApprovedStatus = @PendingStatusId
			--,ApproverId = @ActorId
			,ApprovedDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId

		IF @StatusId = @ApprovedStatusId
		BEGIN
			UPDATE empca
			SET empca.IsKeepInView = 0
				,empca.ShiftId = CASE WHEN kiv.ShiftId IS NOT NULL THEN NULL ELSE empca.ShiftId END
				,empca.ModifiedBy = @ActorId
				,empca.ModifiedDate = @ProcessedDate
			FROM dbo.EmployeeCalendar AS empca WITH (ROWLOCK, UPDLOCK)
				INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON empca.WorkDate = kiv.OnDate
				AND empca.EmpId = kiv.EmpId
				AND kiv.RequestId = @RequestId

			EXEC dbo.KeepInViewRequest_DeleteTrans @RequestId = @RequestId

			EXEC dbo.EmployeeAttendance_ProcessingAndInsert @EmpId
				,@OnDate
				,@OnDate
				,1
		END
	END
	ELSE IF @RoleId = @HRRoleId AND @ProcessedStatusId = @StatusId
	BEGIN
		UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
		SET CurrentStatus = @ApprovedStatusId
			,HRStatus = @PendingStatusId
			,HRId = @ActorId
			,HRDate = @ProcessedDate
			,ModifiedBy = @ActorId
			,ModifiedDate = @ProcessedDate
		WHERE RequestId = @RequestId

		IF @StatusId = @VoidStatusId
		BEGIN
			UPDATE empca
			SET empca.IsKeepInView = 1
				,empca.ShiftId = ISNULL(kiv.ShiftId, empca.ShiftId)
				,empca.ModifiedBy = @ActorId
				,empca.ModifiedDate = @ProcessedDate
			FROM dbo.EmployeeCalendar AS empca WITH (ROWLOCK, UPDLOCK)
				INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON empca.WorkDate = kiv.OnDate
				AND empca.EmpId = kiv.EmpId
				AND kiv.RequestId = @RequestId

			EXEC dbo.KeepInViewRequest_InsertTrans @RequestId = @RequestId

			EXEC dbo.EmployeeAttendance_ProcessingAndInsert @EmpId
				,@OnDate
				,@OnDate
				,1
		END
	END

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @OnDate
		,@toDate = @OnDate
		,@empIds = @EmpId
		,@isUpdateRequestData = 1

	EXEC dbo.KeepInViewRequest_WriteLog @RequestId = @RequestId
		,@Comment = ''
END

GO
/****** Object:  StoredProcedure [dbo].[KeepInViewRequest_Update]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[KeepInViewRequest_Update] @RequestId BIGINT
	,@EmpId INT
	,@Remark NVARCHAR(2000) = NULL
	,@OnDate DATE
	,@KeepInViewType TINYINT
	,@IsHalfDay BIT = NULL
	,@FromTime DATETIME = NULL
	,@ToTime DATETIME = NULL
	,@ModifiedBy INT = NULL
	,@VerifierId INT = NULL
	,@ApproverId INT = NULL
	,@ShiftId INT = NULL
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: 20190522@Quinn.Vo
Task: update keep in view request.
DB: HRM
Original:

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @ModifiedDate DATETIME = GETDATE()
		,@OldOnDate DATE
		,@KeepInViewRequestTypeId TINYINT = 7
		,@IsTopManager BIT
		-- action type
		,@VerifyRequest TINYINT = 2
		,@ApproveRequest TINYINT = 3
		,@OnBehalfRequest TINYINT = 5
		-- keep in view type
		,@KeepInViewByDay TINYINT = 1
		,@KeepInViewByHour TINYINT = 2
		-- request status
		,@PendingStatusId TINYINT = 1
		,@VerifiedStatusId TINYINT = 2
		,@ApprovedStatusId TINYINT = 4
		,@ProcessedStatusId TINYINT = 6

	IF @KeepInViewType = @KeepInViewByDay
		AND @IsHalfDay = 0
	BEGIN
		SELECT @FromTime = NULL
			,@ToTime = NULL
	END

	IF EXISTS (
			SELECT 1
			FROM dbo.WorkingTimeRequest WITH (NOLOCK)
			WHERE RequestId = @RequestId
				AND CurrentStatus <> @PendingStatusId
			)
	BEGIN
		SET @ErrCode = 100
		SET @ErrMsg = 'Status is not pending, you can not edit this request.'

		RETURN;
	END

	IF EXISTS (
			SELECT 1
			FROM dbo.WorkingTimeRequest AS r WITH (NOLOCK)
				INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON r.RequestId = kiv.RequestId
				AND kiv.OnDate = @OnDate
			WHERE r.empid = @empid
				AND r.CurrentStatus IN (@PendingStatusId, @VerifiedStatusId, @ApprovedStatusId, @ProcessedStatusId)
				AND r.RequestId <> @RequestId
			)
	BEGIN
		SET @ErrCode = 101
		SET @ErrMsg = 'There is another request in the same date.'

		RETURN
	END

	IF EXISTS (
			SELECT 1
			FROM dbo.OTDailyRequest WITH (NOLOCK)
			WHERE OvertimeDate = @OnDate
				AND EmpId = @EmpId
				AND (
					NormalHours > 0
					OR OffHours > 0
					OR PublicHours > 0
					OR SpecialHours > 0
					)
			)
	BEGIN
		SET @ErrCode = 103
		SET @ErrMsg = 'You have requested overtime on ' + CONVERT(NVARCHAR(100), @OnDate, 106) + '.'

		RETURN
	END

	IF @KeepInViewType = @KeepInViewByDay
		AND NOT EXISTS (
			SELECT 1
			FROM dbo.EmployeeCalendar WITH (NOLOCK)
			WHERE WorkDate = @OnDate
				AND EmpId = @EmpId
				AND (
					IsHoliday = 1
					OR IsOffDay = 1
					)
			)
	BEGIN
		SET @ErrCode = 102
		SET @ErrMsg = 'Not off day or holiday on ' + CONVERT(NVARCHAR(100), @OnDate, 106)

		RETURN
	END

	IF @EmpId <> @ModifiedBy
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeSupervisor WITH (NOLOCK)
				WHERE OwnerId = @EmpId
					AND EmpId = @ModifiedBy
					AND ActionType = @OnBehalfRequest
					AND RequestType = @KeepInViewRequestTypeId
					AND ISNULL(IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @ModifiedBy
					AND gs.ActionType = @OnBehalfRequest
					AND gs.RequestType = @KeepInViewRequestTypeId
					AND ISNULL(gs.IsDeleted, 0) = 0
				)
		BEGIN
			SET @ErrCode = 104
			SET @ErrMsg = 'You do not have permision.'

			RETURN;
		END
	END

	SELECT @IsTopManager = IsTopManager
	FROM dbo.EmployeeSummary WITH (NOLOCK)
	WHERE EmpId = @EmpId

	IF (
			@ApproverId IS NULL
			OR @VerifierId IS NULL
			)
		AND @IsTopManager = 0
	BEGIN
		SET @ErrCode = 105
		SET @ErrMsg = 'Verifier, Approver is required.'

		RETURN;
	END

	IF @IsTopManager = 0
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeSupervisor WITH (NOLOCK)
				WHERE OwnerId = @VerifierId
					AND EmpId = @EmpId
					AND ActionType = @VerifyRequest
					AND RequestType = @KeepInViewRequestTypeId
					AND ISNULL(IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @VerifierId
					AND ISNULL(gs.IsDeleted, 0) = 0
					AND gs.RequestType = @KeepInViewRequestTypeId
					AND gs.ActionType = @VerifyRequest
				)
		BEGIN
			SET @ErrCode = 106
			SET @ErrMsg = 'Verifier is invalid.'

			RETURN;
		END

		IF NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeSupervisor WITH (NOLOCK)
				WHERE OwnerId = @ApproverId
					AND EmpId = @EmpId
					AND ActionType = @ApproveRequest
					AND RequestType = @KeepInViewRequestTypeId
					AND ISNULL(IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @ApproverId
					AND ISNULL(gs.IsDeleted, 0) = 0
					AND gs.RequestType = @KeepInViewRequestTypeId
					AND gs.ActionType = @ApproveRequest
				)
		BEGIN
			SET @ErrCode = 107
			SET @ErrMsg = 'Approver is invalid.'

			RETURN;
		END
	END

	IF DATEDIFF(MI, @FromTime, @ToTime) < 60
	BEGIN
		SET @ErrCode = 108
		SET @ErrMsg = 'Minimum Compensation Leave is 60 minutes.'

		RETURN;
	END

	SELECT @OldOnDate = OnDate
	FROM dbo.KeepInViewRequest WITH (NOLOCK)
	WHERE RequestId = @RequestId

	UPDATE dbo.WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
	SET Remark = @Remark
		,CurrentStatus = CASE 
			WHEN @IsTopManager = 1
				AND @VerifierId IS NOT NULL THEN @PendingStatusId
			WHEN @IsTopManager = 1
				AND @ApproverId IS NOT NULL THEN @VerifiedStatusId
			WHEN @IsTopManager = 1
				AND @ApproverId IS NULL THEN @ApprovedStatusId
			ELSE @PendingStatusId
			END
		,VerifierId = @VerifierId
		,VerifiedStatus = CASE 
			WHEN @IsTopManager = 1
				AND @VerifierId IS NULL THEN @VerifiedStatusId
			ELSE @PendingStatusId
			END
		,ApproverId = @ApproverId
		,ApprovedStatus = CASE 
			WHEN @IsTopManager = 1
				AND @ApproverId IS NULL THEN @VerifiedStatusId
			ELSE @PendingStatusId
			END
		,ModifiedBy = @ModifiedBy
		,ModifiedDate = @ModifiedDate
	WHERE RequestId = @RequestId

	UPDATE dbo.KeepInViewRequest WITH (ROWLOCK, UPDLOCK)
	SET OnDate = @OnDate
		,KeepInViewType = @KeepInViewType
		,IsHalfDay = @IsHalfDay
		,FromTime = @FromTime
		,ToTime = @ToTime
		,ShiftId = @ShiftId
	WHERE RequestId = @RequestId

	IF @ApproverId IS NULL
		AND @VerifierId IS NULL
		AND @IsTopManager = 1
	BEGIN
		EXEC dbo.KeepInViewRequest_Approve @RequestId = @RequestId
			,@ActorId = @EmpId
			,@RoleId = 3
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END

	IF @OldOnDate <> @OnDate
	BEGIN
		EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @OldOnDate
			,@toDate = @OldOnDate
			,@empIds = @EmpId
			,@isUpdateRequestData = 1
	END

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @OnDate
		,@toDate = @OnDate
		,@empIds = @EmpId
		,@isUpdateRequestData = 1

	EXEC dbo.KeepInViewRequest_WriteLog @RequestId
END
GO
