CREATE PROCEDURE [dbo].[LateInEarlyOutRequest_Update] @RequestId BIGINT
	,@EmpId INT
	,@OnDate DATE
	,@RequestType SMALLINT
	,@ReasonId TINYINT
	,@LateInMins INT = NULL
	,@EarlyOutMins INT = NULL
	,@Remark NVARCHAR(2000) = NULL
	,@ModifiedBy INT = NULL
	,@VerifierId INT = NULL
	,@ApproverId INT = NULL
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: Quinn.Vo@20190625
Task: Edit a late in/early out request
DB: HRM
Original:

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @ModifiedDate DATETIME = GETDATE()
		,@IsTopManager BIT
		-- leave type
		,@AnnualLeaveTypeId TINYINT = 2
		,@UnpaidLeaveTypeId TINYINT = 25
		-- action type
		,@VerifyRequest TINYINT = 2
		,@ApproveRequest TINYINT = 3
		,@OnBehalfRequest TINYINT = 5
		-- request type
		,@LateInRequestTypeId TINYINT = 3
		,@EarlyOutRequestTypeId TINYINT = 4
		-- request status
		,@PendingStatusId TINYINT = 1
		,@VerifiedStatusId TINYINT = 2
		,@ApprovedStatusId TINYINT = 4
		,@ProcessedStatusId TINYINT = 6

	IF EXISTS (
			SELECT 1
			FROM dbo.WorkingTimeRequest WITH (NOLOCK)
			WHERE RequestId = @RequestId
				AND CurrentStatus <> @PendingStatusId
			)
	BEGIN
		SET @ErrCode = 100
		SET @ErrMsg = 'Status is not pending, you can not edit this request.'

		RETURN;
	END

	IF EXISTS (
			SELECT 1
			FROM dbo.WorkingTimeRequest AS wk WITH (NOLOCK)
				INNER JOIN dbo.LateInEarlyOutRequest AS lieo WITH (NOLOCK) ON wk.RequestId = lieo.RequestId
				AND lieo.RequestId <> @RequestId
				AND lieo.OnDate = @OnDate
			WHERE wk.EmpId = @EmpId
				AND wk.RequestType = @RequestType
				AND wk.CurrentStatus IN (@PendingStatusId, @VerifiedStatusId, @ApprovedStatusId, @ProcessedStatusId)
			)
	BEGIN
		SET @ErrCode = 101
		SET @ErrMsg = 'There is another request in the same date.'

		RETURN;
	END

	SELECT @IsTopManager = IsTopManager
	FROM dbo.EmployeeSummary WITH (NOLOCK)
	WHERE EmpId = @EmpId

	IF (
			@ApproverId IS NULL
			OR @VerifierId IS NULL
			)
		AND @IsTopManager = 0
	BEGIN
		SET @ErrCode = 102
		SET @ErrMsg = 'Verifier, Approver is required.'

		RETURN;
	END

	IF @EmpId <> @ModifiedBy
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeSupervisor AS sp WITH (NOLOCK)
				WHERE sp.OwnerId = @EmpId
					AND sp.EmpId = @ModifiedBy
					AND sp.ActionType = @OnBehalfRequest
					AND sp.RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND ISNULL(sp.IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @ModifiedBy
					AND gs.ActionType = @OnBehalfRequest
					AND gs.RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND ISNULL(gs.IsDeleted, 0) = 0
				)
		BEGIN
			SET @ErrCode = 103
			SET @ErrMsg = 'You do not have permision.'

			RETURN;
		END
	END

	IF @IsTopManager = 0
	BEGIN
		IF NOT EXISTS (
				SELECT TOP 1 1
				FROM dbo.EmployeeSupervisor WITH (NOLOCK)
				WHERE OwnerId = @VerifierId
					AND EmpId = @EmpId
					AND ActionType = @VerifyRequest
					AND RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND ISNULL(IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @VerifierId
					AND gs.RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND gs.ActionType = @VerifyRequest
					AND ISNULL(gs.IsDeleted, 0) = 0
				)
		BEGIN
			SET @ErrCode = 104
			SET @ErrMsg = 'Verifier is invalid.'

			RETURN;
		END

		IF NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeSupervisor WITH (NOLOCK)
				WHERE OwnerId = @ApproverId
					AND EmpId = @EmpId
					AND ActionType = @ApproveRequest
					AND RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND ISNULL(IsDeleted, 0) = 0
				)
			AND NOT EXISTS (
				SELECT 1
				FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
					AND emp.EmpId = @EmpId
				WHERE gs.OwnerId = @ApproverId
					AND gs.RequestType IN (@LateInRequestTypeId, @EarlyOutRequestTypeId)
					AND gs.ActionType = @ApproveRequest
					AND ISNULL(gs.IsDeleted, 0) = 0
				)
		BEGIN
			SET @ErrCode = 105
			SET @ErrMsg = 'Approver is invalid.'

			RETURN;
		END
	END

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @OnDate
		,@toDate = @OnDate
		,@empIds = @EmpId

	IF EXISTS (
			SELECT 1
			FROM dbo.tmpEmployeeCalendar WITH (NOLOCK)
			WHERE EmpId = @EmpId
				AND WorkDate = @OnDate
				AND LeaveTypeId IN (@AnnualLeaveTypeId, @UnpaidLeaveTypeId)
				AND IsLeaveDay = 1
				AND LeaveDay = 0.5
			)
		AND (
			@LateInMins > 30
			OR @EarlyOutMins > 30
			)
	BEGIN
		SET @ErrCode = 106
		SET @ErrMsg = 'You can not request over 30 minutes on half day leave.'

		RETURN
	END

	UPDATE WorkingTimeRequest WITH (ROWLOCK, UPDLOCK)
	SET Remark = @Remark
		,CurrentStatus = CASE 
			WHEN @IsTopManager = 1
				AND @VerifierId IS NOT NULL THEN @PendingStatusId
			WHEN @IsTopManager = 1
				AND @ApproverId IS NOT NULL THEN @VerifiedStatusId
			WHEN @IsTopManager = 1
				AND @ApproverId IS NULL THEN @ApprovedStatusId
			ELSE @PendingStatusId
			END
		,VerifierId = @VerifierId
		,VerifiedStatus = CASE 
			WHEN @IsTopManager = 1
				AND @VerifierId IS NULL THEN @VerifiedStatusId
			ELSE @PendingStatusId
			END
		,ApproverId = @ApproverId
		,ApprovedStatus = CASE 
			WHEN @IsTopManager = 1
				AND @ApproverId IS NULL THEN @VerifiedStatusId
			ELSE @PendingStatusId
			END
		,ModifiedBy = @ModifiedBy
		,ModifiedDate = @ModifiedDate
	WHERE RequestId = @RequestId

	UPDATE dbo.LateInEarlyOutRequest WITH (ROWLOCK, UPDLOCK)
	SET EmpId = @EmpId
		,LateInMins = @LateInMins
		,EarlyOutMins = @EarlyOutMins
		,OnDate = @OnDate
		,ReasonId = @ReasonId
	WHERE RequestId = @RequestId

	IF @ApproverId IS NULL
		AND @VerifierId IS NULL
		AND @IsTopManager = 1
	BEGIN
		EXEC dbo.LateInEarlyOutRequest_Approve @RequestId = @RequestId
			,@ActorId = @EmpId
			,@RoleId = 3
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END

	EXEC dbo.LateInEarlyOutRequest_WriteLog @RequestId = @RequestId
END



GO
/****** Object:  StoredProcedure [dbo].[LateInEarlyOutRequest_UpdateDiscipline]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[LateInEarlyOutRequest_UpdateDiscipline] @RequestId BIGINT
	,@ActorId INT
	,@RequestStatusId TINYINT
	,@DisciplineXml NVARCHAR(MAX) = NULL
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: 20191203@Tim.Trinh
Task: update discipline.
DB: HRM
Original:

Revisions:
	- 03082023@Otis: skip discipline in case Management Allow
	- 12182024@Lilac: skip discipline in case Xmas / New Year, Wedding
Param's Explanation:
    @DisciplineXml:
        <Root>
            <Row WorkDate='' EmployeeId='' DisciplineTypeId='' IsIgnored='' IsConfirmed='' />
        </Root>
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @ModifiedDate DATETIME = GETDATE()
		,@ReasonId TINYINT
		-- late in/early out reason
		,@ManagementAllowReasonId TINYINT = 1
		,@XmasNewYear TINYINT = 3
		,@Wedding TINYINT = 4
		-- request status
		,@PendingStatusId TINYINT = 1
		,@NotVerifiedStatusId TINYINT = 3
		,@RejectedStatusId TINYINT = 5
		,@VoidStatusId TINYINT = 7
	DECLARE @tblDiscipline TABLE (
		WorkDate DATE
		,EmpId INT
		,DisciplineTypeId INT
		,IsIgnored BIT
		,IsConfirmed BIT
		)

	-- reset/reject request
	IF @RequestStatusId = @PendingStatusId
		OR @RequestStatusId = @NotVerifiedStatusId
		OR @RequestStatusId = @RejectedStatusId
		OR @RequestStatusId = @VoidStatusId
	BEGIN
		DELETE did
		FROM dbo.DisciplineIgnoreDetail AS did WITH (ROWLOCK, UPDLOCK)
			INNER JOIN DisciplineRequestTrans AS dtran WITH (NOLOCK) ON did.EmpId = dtran.EmpId
			AND did.DisciplineTypeId = dtran.DisciplineTypeId
			AND did.WorkDate = dtran.WorkDate
		WHERE dtran.RequestId = @RequestId

		EXEC dbo.DisciplineRequestTrans_Delete @RequestId = @RequestId

		UPDATE dis
		SET dis.IsLateIn = CASE 
				WHEN r.RequestType = 3 THEN CASE 
						WHEN @RequestStatusId = @PendingStatusId THEN 1
						ELSE 0
						END
				ELSE dis.IsLateIn
				END
			,dis.IsEarlyOut = CASE 
				WHEN r.RequestType = 4 THEN CASE 
						WHEN @RequestStatusId = @PendingStatusId THEN 1
						ELSE 0
						END
				ELSE dis.IsEarlyOut
				END
			,dis.IsOutOfControlReason = CASE 
				WHEN outofctrl.EmpId IS NULL
					OR (
						outofctrl.IsOutOfControlChangeShift = 0
						AND outofctrl.IsOutOfControlMissingCheckInOut = 0
						AND (
							(
								r.RequestType = 3
								AND outofctrl.IsOutOfControlEarlyOut = 0
								)
							OR (
								r.RequestType = 4
								AND outofctrl.IsOutOfControlLateIn = 0
								)
							)
						AND outofctrl.IsOutOfControlAbsent = 0
						AND outofctrl.IsOutOfControlUnpaidLeave = 0
						AND outofctrl.IsOutOfControlWorkingUnderTime = 0
						AND outofctrl.IsOutOfControlUnpaidLeaveAbsent = 0
						AND outofctrl.IsOutOfControlUnplannedLeave = 0
						AND outofctrl.IsOutOfControlWeekendLeave = 0
						) THEN 0
				ELSE dis.IsOutOfControlReason
				END
			,dis.IsDeleted = CASE 
				WHEN @RequestStatusId = @PendingStatusId THEN 1
				ELSE dis.IsDeleted
				END
			,dis.ModifiedBy = @ActorId
			,dis.ModifiedDate = @ModifiedDate
		FROM dbo.Discipline AS dis WITH (ROWLOCK, UPDLOCK)
			INNER JOIN dbo.LateInEarlyOutRequest AS lieo WITH (NOLOCK) ON lieo.RequestId = @RequestId
			AND dis.EmpId = lieo.EmpId
			AND dis.WorkDate = lieo.OnDate
			INNER JOIN dbo.WorkingTimeRequest AS r WITH (NOLOCK) ON lieo.RequestId = r.RequestId
			LEFT JOIN dbo.DisciplineOutOfControl AS outofctrl WITH (NOLOCK) ON dis.EmpId = outofctrl.EmpId
			AND dis.WorkDate = outofctrl.WorkDate
		WHERE EXISTS (
				SELECT 1
				FROM dbo.Employee AS emp WITH (NOLOCK)
					INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND (
						(
							drule.DisciplineTypeId = 3
							AND r.RequestType = 3
							)
						OR (
							drule.DisciplineTypeId = 4
							AND r.RequestType = 4
							)
						)
					AND empsum.IsLocal = drule.IsLocal
					AND drule.Value = 1
				WHERE dis.EmpId = emp.EmpId
				)

		UPDATE dis
		SET dis.IsIgnoredLateIn = CASE 
				WHEN r.RequestType = 3 THEN 0
				ELSE dis.IsIgnoredLateIn
				END
			,dis.IsIgnoredEarlyOut = CASE 
				WHEN r.RequestType = 4 THEN 0
				ELSE dis.IsIgnoredEarlyOut
				END
		FROM dbo.DisciplineIgnore AS dis WITH (ROWLOCK, UPDLOCK)
			INNER JOIN dbo.LateInEarlyOutRequest AS lieo WITH (NOLOCK) ON lieo.RequestId = @RequestId
			AND dis.EmpId = lieo.EmpId
			AND dis.WorkDate = lieo.OnDate
			INNER JOIN dbo.WorkingTimeRequest AS r WITH (NOLOCK) ON lieo.RequestId = r.RequestId
		WHERE EXISTS (
				SELECT 1
				FROM dbo.Employee AS emp WITH (NOLOCK)
					INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND (
						(
							drule.DisciplineTypeId = 3
							AND r.RequestType = 3
							)
						OR (
							drule.DisciplineTypeId = 4
							AND r.RequestType = 4
							)
						)
					AND empsum.IsLocal = drule.IsLocal
					AND drule.Value = 1
				WHERE dis.EmpId = emp.EmpId
				)

		UPDATE dis
		SET dis.IsOutOfControlLateIn = CASE 
				WHEN r.RequestType = 3 THEN 0
				ELSE dis.IsOutOfControlLateIn
				END
			,dis.IsOutOfControlEarlyOut = CASE 
				WHEN r.RequestType = 4 THEN 0
				ELSE dis.IsOutOfControlEarlyOut
				END
		FROM dbo.DisciplineOutOfControl AS dis WITH (ROWLOCK, UPDLOCK)
			INNER JOIN dbo.LateInEarlyOutRequest AS lieo WITH (NOLOCK) ON lieo.RequestId = @RequestId
			AND dis.EmpId = lieo.EmpId
			AND dis.WorkDate = lieo.OnDate
			INNER JOIN dbo.WorkingTimeRequest AS r WITH (NOLOCK) ON lieo.RequestId = r.RequestId
		WHERE EXISTS (
				SELECT 1
				FROM dbo.Employee AS emp WITH (NOLOCK)
					INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND (
						(
							drule.DisciplineTypeId = 3
							AND r.RequestType = 3
							)
						OR (
							drule.DisciplineTypeId = 4
							AND r.RequestType = 4
							)
						)
					AND empsum.IsLocal = drule.IsLocal
					AND drule.Value = 1
				WHERE dis.EmpId = emp.EmpId
				)

		RETURN
	END

	-- approve request
	IF ISNULL(@DisciplineXml, '') <> ''
	BEGIN
		BEGIN TRY
			DECLARE @DocHandler INT

			EXEC sp_xml_preparedocument @DocHandler OUTPUT
				,@DisciplineXml

			INSERT INTO @tblDiscipline (
				WorkDate
				,EmpId
				,DisciplineTypeId
				,IsIgnored
				,IsConfirmed
				)
			SELECT DISTINCT WorkDate
				,EmployeeId
				,DisciplineTypeId
				,IsIgnored
				,IsConfirmed
			FROM OPENXML(@DocHandler, '/Root/Row', 1) WITH (WorkDate DATE, EmployeeId INT, DisciplineTypeId INT, IsIgnored BIT, IsConfirmed BIT) AS Data

			EXEC sp_xml_removedocument @DocHandler
		END TRY

		BEGIN CATCH
			SELECT @ErrCode = 1
				,@ErrMsg = N'Parameter invalid.'

			RETURN
		END CATCH
	END

	BEGIN TRY
		IF EXISTS (
				SELECT 1
				FROM @tblDiscipline
				)
		BEGIN
			SELECT @ReasonId = ReasonId
			FROM dbo.LateInEarlyOutRequest WITH (NOLOCK)
			WHERE RequestId = @RequestId

			INSERT INTO dbo.DisciplineRequestTrans (
				EmpId
				,WorkDate
				,RequestId
				,DisciplineTypeId
				,IsIgnored
				,IsOutOfControl
				,ModifiedBy
				,ModifiedDate
				)
			SELECT EmpId
				,WorkDate
				,@RequestId
				,DisciplineTypeId
				,IsIgnored
				,0
				,@ActorId
				,@ModifiedDate
			FROM @tblDiscipline
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)

			-- update
			UPDATE dis
			SET dis.IsLateIn = CASE 
					WHEN tbl.DisciplineTypeId = 3 THEN 1
					ELSE 0
					END
				,dis.IsEarlyOut = CASE 
					WHEN tbl.DisciplineTypeId = 4 THEN 1
					ELSE 0
					END
				,dis.IsDeleted = 0
				,dis.ModifiedBy = @ActorId
				,dis.ModifiedDate = @ModifiedDate
			FROM dbo.Discipline AS dis WITH (ROWLOCK, UPDLOCK)
				INNER JOIN @tblDiscipline AS tbl ON dis.WorkDate = tbl.WorkDate
				AND dis.EmpId = tbl.EmpId
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)

			UPDATE dis
			SET dis.IsIgnoredLateIn = CASE 
					WHEN tbl.DisciplineTypeId = 3 THEN tbl.IsIgnored
					ELSE 0
					END
				,dis.IsIgnoredEarlyOut = CASE 
					WHEN tbl.DisciplineTypeId = 4 THEN tbl.IsIgnored
					ELSE 0
					END
			FROM dbo.DisciplineIgnore AS dis WITH (ROWLOCK, UPDLOCK)
				INNER JOIN @tblDiscipline AS tbl ON dis.WorkDate = tbl.WorkDate
				AND dis.EmpId = tbl.EmpId
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)

			UPDATE dis
			SET dis.IsOutOfControlLateIn = CASE 
					WHEN tbl.DisciplineTypeId = 3
						AND (@ReasonId = @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)
						AND IsIgnored = 1 THEN 1
					ELSE 0
					END
				,dis.IsOutOfControlEarlyOut = CASE 
					WHEN tbl.DisciplineTypeId = 4
						AND (@ReasonId = @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)
						AND IsIgnored = 1 THEN 1
					ELSE 0
					END
			FROM dbo.DisciplineOutOfControl AS dis WITH (ROWLOCK, UPDLOCK)
				INNER JOIN @tblDiscipline AS tbl ON dis.WorkDate = tbl.WorkDate
				AND dis.EmpId = tbl.EmpId
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)

			-- insert
			INSERT INTO dbo.Discipline (
				EmpId
				,WorkDate
				,IsLateIn
				,IsEarlyOut
				,IsOutOfControlReason
				,ModifiedBy
				,ModifiedDate
				)
			SELECT EmpId
				,WorkDate
				,CASE 
					WHEN tbl.DisciplineTypeId = 3 THEN 1
					ELSE 0
					END
				,CASE 
					WHEN tbl.DisciplineTypeId = 4 THEN 1
					ELSE 0
					END
				,0
				,@ActorId
				,@ModifiedDate
			FROM @tblDiscipline AS tbl
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)
				AND NOT EXISTS (
					SELECT 1
					FROM dbo.Discipline AS dis WITH (NOLOCK)
					WHERE dis.EmpId = tbl.EmpId
						AND dis.WorkDate = tbl.WorkDate
					)

			INSERT INTO dbo.DisciplineIgnore (
				EmpId
				,WorkDate
				,IsIgnoredLateIn
				,IsIgnoredEarlyOut
				)
			SELECT EmpId
				,WorkDate
				,CASE 
					WHEN tbl.DisciplineTypeId = 3 THEN IsIgnored
					ELSE 0
					END
				,CASE 
					WHEN tbl.DisciplineTypeId = 4 THEN IsIgnored
					ELSE 0
					END
			FROM @tblDiscipline AS tbl
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)
				AND NOT EXISTS (
					SELECT 1
					FROM dbo.DisciplineIgnore AS dis WITH (NOLOCK)
					WHERE dis.EmpId = tbl.EmpId
						AND dis.WorkDate = tbl.WorkDate
					)

			INSERT INTO dbo.DisciplineOutOfControl (
				EmpId
				,WorkDate
				,IsOutOfControlLateIn
				,IsOutOfControlEarlyOut
				)
			SELECT EmpId
				,WorkDate
				,0
				,0
			FROM @tblDiscipline AS tbl
			WHERE (@ReasonId != @ManagementAllowReasonId AND @ReasonId != @XmasNewYear AND @ReasonId != @Wedding)
				AND NOT EXISTS (
					SELECT 1
					FROM dbo.DisciplineOutOfControl AS dis WITH (NOLOCK)
					WHERE dis.EmpId = tbl.EmpId
						AND dis.WorkDate = tbl.WorkDate
					)
		END
	END TRY

	BEGIN CATCH
		SELECT @ErrCode = 1
			,@ErrMsg = N'Update discipline unsuccessfully.'
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[LateInEarlyOutRequest_VoidBySA]    Script Date: 2/13/2025 1:39:30 PM ******/
SET ANSI_NULLS ON
