CREATE PROCEDURE [dbo].[LeaveRequest_UpdateTmpKIVLeaveTrans] 
	@RequestId BIGINT
	,@EmpID INT
	,@Status INT = 1
AS
/*
Created: Quinn.Vo@20150927
Task: Update KIV temp.
DB: HRM
Original: 

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @KIVLeave NUMERIC(18, 2)

	IF (@Status = 2)
	BEGIN
		SELECT @KIVLeave = SUM(TotalDays)
		FROM dbo.tmpKIVLeaveBalance WITH (NOLOCK)
		WHERE Requestid = @Requestid
			AND [Status] <> 2

	END
	ELSE
	BEGIN
		SELECT @KIVLeave = SUM(TotalDays)
		FROM dbo.tmpKIVLeaveBalance WITH (NOLOCK)
		WHERE Requestid = @Requestid
			AND [Status] = 2
	END

	UPDATE dbo.[tmpKIVLeaveBalance] WITH (ROWLOCK, UPDLOCK)
	SET [Status] = @Status
	WHERE Requestid = @Requestid
END



