CREATE PROCEDURE [dbo].[Report_EmployeeCalendarByWeekly] @empId INT = NULL
	,@fromtime DATE
	,@totime DATE
	,@TeamIds VARCHAR(MAX) = ''
	,@JobTitleId VARCHAR(MAX) = ''
	,@isLocal BIT = NULL
AS
/*
Created: Tom.Vo@2013-11-15
Task: view employee calendar by weekly
DB: HRM_SMS
Original:

Revisions:
	- 20200714@Merlin.Le: Get section and department code
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @EmployeeIds VARCHAR(MAX)
	DECLARE @tblGroupIds TABLE (GroupId INT)
	DECLARE @tblJobTitleIds TABLE (JobTitleId INT)
	CREATE TABLE #tblEmployeeIds (EmployeeId INT)

	IF ISNULL(@TeamIds, '') <> ''
		INSERT INTO @tblGroupIds (GroupId)
		SELECT DISTINCT val
		FROM dbo.fnc_strSplit(@TeamIds, ',')
	
	IF ISNULL(@JobTitleId, '') <> ''
		INSERT INTO @tblJobTitleIds (JobTitleId)
		SELECT DISTINCT val
		FROM dbo.fnc_strSplit(@JobTitleId, ',')
	ELSE
	BEGIN
		INSERT INTO @tblJobTitleIds (JobTitleId)
		SELECT DISTINCT lk.Id
		FROM dbo.LookupData AS lk WITH (NOLOCK)
		WHERE lk.LookupId = 1
	END

	INSERT INTO #tblEmployeeIds (EmployeeId)
	SELECT emp.EmpId
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
		AND (
			@isLocal IS NULL
			OR empsum.IsLocal = @isLocal
			)
		INNER JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
	WHERE emp.[Enabled] = 1
		AND emp.isDeleted = 0
		AND (
			@empId IS NULL
			OR emp.EmpId = @empId
			)
		AND EXISTS (
			SELECT 1
			FROM @tblGroupIds AS tbl
			WHERE emp.GroupId = tbl.GroupId
			)
		AND EXISTS (
			SELECT 1
			FROM @tblJobTitleIds AS tbl
			WHERE emp.JobTitleId = tbl.JobTitleId
			)

	SELECT @EmployeeIds = COALESCE(@EmployeeIds + ',', '') + CAST(EmployeeId AS VARCHAR(10))
	FROM #tblEmployeeIds WITH (NOLOCK)

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @fromtime
		,@toDate = @totime
		,@empIds = @EmployeeIds
		,@isEnable = 1
		,@isDelete = 0

	SELECT emp.EmpId AS EmployeeId
		,emp.Code
		,emp.NickName
		,emp.FullName
		,gr.[Name] AS Team
		,sec.Code AS SectionCode
		,dep.Code AS DepartmentCode
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN #tblEmployeeIds AS tblemp WITH (NOLOCK) ON emp.EmpId = tblemp.EmployeeId
		INNER JOIN dbo.EmployeeSummary AS esum WITH (NOLOCK) ON emp.EmpId = esum.EmpId
		INNER JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
		INNER JOIN dbo.[Section] AS sec WITH (NOLOCK) ON gr.SectionId = sec.SectionId
		INNER JOIN dbo.[Department] AS dep WITH (NOLOCK) ON sec.DepartmentId = dep.DepartmentId
	ORDER BY gr.[Name]
		,emp.Code

	SELECT emp.EmpId AS EmployeeId
		,emp.NickName
		,empca.WorkDate
		,empca.IsOvertime
		,empca.IsLeaveOffDay
		,empca.ChangeShiftTypeId
		,empca.MoveOffFromDate
		,empca.MoveOffToDate
		,empca.IsHoliday
		,empca.IsOffDay
		,empca.IsLeaveDay
		,empca.IsKeepInView
		,empca.LeaveDay
		,(CASE 
			WHEN offrep.EmployeeId IS NOT NULL THEN 1
			ELSE 0 END
			) AS IsOffDayReplacement
		,shift.ShiftId
		,shift.Code
		,shift.[Name]
		,shift.BeginCheckInTime AS CheckIn
		,shift.BeginCheckOutTime AS CheckOut
		,shift.IsInAfterDay
		,shift.IsOutAfterDay
		,lv1.LeaveTypeId
		,lv1.Code
		,lv1.[Name]
		,empca.FromTime
		,empca.ToTime
		,lv2.LeaveTypeId AS LeaveTypeId2
		,lv2.Code
		,lv2.[Name]
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN #tblEmployeeIds AS tblemp WITH (NOLOCK) ON emp.EmpId = tblemp.EmployeeId
		INNER JOIN dbo.tmpEmployeeCalendar AS empca ON emp.EmpId = empca.EmpId
		AND empca.WorkDate BETWEEN @fromTime
			AND @toTime
		LEFT JOIN dbo.Shift AS shift WITH (NOLOCK) ON shift.ShiftId = empca.ShiftId
		LEFT JOIN dbo.LeaveType AS lv1 WITH (NOLOCK) ON empca.LeaveTypeId = lv1.LeaveTypeId
		LEFT JOIN dbo.LeaveType AS lv2 WITH (NOLOCK) ON empca.LeaveTypeId2 = lv2.LeaveTypeId
		LEFT JOIN dbo.ScheduleArrangementOffDayReplacement AS offrep WITH (NOLOCK) ON emp.EmpId = offrep.EmployeeId
		AND empca.WorkDate = offrep.WorkDate
	ORDER BY emp.NickName
		,empca.WorkDate

	DROP TABLE #tblEmployeeIds
END

GO
/****** Object:  StoredProcedure [dbo].[Report_GetWeekendLeaveDetail]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Report_GetWeekendLeaveDetail] @FromDate DATE
	,@ToDate DATE
	,@TeamId VARCHAR(MAX) = ''
	,@EmployeeId INT = NULL
	,@IsLocal BIT = NULL
	,@LeaveTypeId INT = NULL
	,@SupervisorId INT = NULL
AS
BEGIN
	SET NOCOUNT ON;

	CREATE TABLE #tblGroupIds (TmpGroupId INT)

	IF ISNULL(@TeamId, '') <> ''
	BEGIN
		INSERT INTO #tblGroupIds (TmpGroupId)
		SELECT DISTINCT val
		FROM fnc_strSplit(@TeamId, ',')
	END

	CREATE TABLE #tblEmployeeId (EmpId INT)

	IF (@EmployeeId IS NULL)
	BEGIN
		INSERT INTO #tblEmployeeId (EmpId)
		SELECT DISTINCT EmpId
		FROM [dbo].[fnc_GetEmployeeByActorId](@SupervisorId, 1, 0)
	END
	ELSE
	BEGIN
		INSERT INTO #tblEmployeeId (EmpId)
		VALUES (@EmployeeId)
	END

	-- half day
	SELECT EmployeeId
		,NickName
		,FullName
		,Code
		,IsLocal
		,GroupId AS TeamId
		,GroupName AS TeamName
		,GroupCode AS TeamCode
		,LeaveDate
		,LeaveTypeId
		,LeaveType
		,LeaveDay
		,Remark
		,ApproverComment
	FROM (
		SELECT emp.EmpId AS EmployeeId
			,emp.NickName
			,emp.FullName
			,emp.Code
			,empSum.IsLocal
			,gr.GroupId
			,gr.[Name] AS GroupName
			,gr.Code AS GroupCode
			,empC.WorkDate AS LeaveDate
			,ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) AS LeaveTypeId
			,lt.NAME AS LeaveType
			,empC.LeaveDay
			,STUFF((
					SELECT ', ' + rq.Remark
					FROM dbo.LeaveRequestDetail AS ldt WITH (NOLOCK)
						INNER JOIN [dbo].[WorkingTimeRequest] AS rq WITH (NOLOCK) ON ldt.[RequestId] = rq.[RequestId]
					WHERE ldt.EmpId = emp.EmpId
						AND ldt.OnDate = empC.WorkDate
						AND rq.CurrentStatus IN (4, 6)
					FOR XML PATH('')
					), 1, 1, '') AS Remark
			,STUFF((
					SELECT ', ' + rq.ApproverComment
					FROM dbo.LeaveRequestDetail AS ldt WITH (NOLOCK)
						INNER JOIN [dbo].[WorkingTimeRequest] AS rq WITH (NOLOCK) ON ldt.[RequestId] = rq.[RequestId]
					WHERE ldt.EmpId = emp.EmpId
						AND ldt.OnDate = empC.WorkDate
						AND rq.CurrentStatus IN (4, 6)
					FOR XML PATH('')
					), 1, 1, '') AS ApproverComment
		FROM dbo.Employee AS emp WITH (NOLOCK)
			INNER JOIN #tblEmployeeId AS em ON emp.EmpId = em.EmpId
			INNER JOIN dbo.EmployeeCalendar AS empC WITH (NOLOCK) ON empC.EmpId = emp.EmpId
			INNER JOIN dbo.EmployeeSummary AS empSum WITH (NOLOCK) ON empSum.EmpId = emp.EmpId
			INNER JOIN dbo.LeaveType AS lt WITH (NOLOCK) ON ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) = lt.LeaveTypeId
			INNER JOIN dbo.LeaveRequestDetail AS ldt WITH (NOLOCK) ON ldt.EmpId = emp.EmpId
			AND ldt.OnDate = empC.WorkDate
			AND ldt.IsHalfDay = 1
			INNER JOIN [dbo].[WorkingTimeRequest] AS rq WITH (NOLOCK) ON ldt.[RequestId] = rq.[RequestId]
			AND rq.CurrentStatus IN (4, 6)
			INNER JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
		WHERE emp.[Enabled] = 1
			AND ISNULL(emp.IsDeleted, 0) = 0
			AND EXISTS (
			SELECT 1
			FROM #tblGroupIds AS tbl
			WHERE emp.GroupId = tbl.TmpGroupId
			)
			AND ISNULL(@EmployeeId, emp.EmpId) = emp.EmpId
			AND ISNULL(@IsLocal, empSum.IsLocal) = empSum.IsLocal
			AND (
				DATENAME(DW, empC.WorkDate) = 'Saturday'
				OR DATENAME(DW, empC.WorkDate) = 'Sunday'
				)
			AND empC.IsLeaveDay != 0
			AND (
				empC.LeaveTypeId = 2
				OR empC.LeaveTypeId = 25
				OR empC.LeaveTypeId2 = 2
				OR empC.LeaveTypeId2 = 25
				)
			AND empC.WorkDate BETWEEN @FromDate
				AND @ToDate
			AND (
				@LeaveTypeId = - 1
				OR empC.LeaveTypeId = @LeaveTypeId
				OR empC.LeaveTypeId2 = @LeaveTypeId
				)
		
		UNION
		-- general leave # half day
		SELECT emp.EmpId AS EmployeeId
			,emp.NickName
			,emp.FullName
			,emp.Code
			,empSum.IsLocal
			,gr.GroupId AS TeamId
			,gr.[Name] AS TeamName
			,gr.Code AS TeamCode
			,empC.WorkDate AS LeaveDate
			,ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) AS LeaveTypeId
			,lt.NAME AS LeaveType
			,empC.LeaveDay
			,rq.Remark
			,rq.ApproverComment
		FROM dbo.Employee AS emp WITH (NOLOCK)
			INNER JOIN #tblEmployeeId AS em ON emp.EmpId = em.EmpId
			INNER JOIN dbo.EmployeeCalendar AS empC WITH (NOLOCK) ON empC.EmpId = emp.EmpId
			INNER JOIN dbo.EmployeeSummary AS empSum WITH (NOLOCK) ON empSum.EmpId = emp.EmpId
			INNER JOIN dbo.LeaveType AS lt WITH (NOLOCK) ON ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) = lt.LeaveTypeId
			INNER JOIN dbo.LeaveRequestDetail AS ldt WITH (NOLOCK) ON ldt.EmpId = emp.EmpId
			AND ldt.OnDate = empC.WorkDate
			AND ldt.IsHalfDay = 0
			INNER JOIN dbo.LeaveRequest AS le WITH (NOLOCK) ON ldt.RequestId = le.RequestId
			AND le.LeaveType = 0
			INNER JOIN [dbo].[WorkingTimeRequest] AS rq WITH (NOLOCK) ON ldt.[RequestId] = rq.[RequestId]
			AND rq.CurrentStatus IN (4, 6)
			INNER JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
		WHERE emp.[Enabled] = 1
			AND ISNULL(emp.IsDeleted, 0) = 0
			AND EXISTS (
			SELECT 1
			FROM #tblGroupIds AS tbl
			WHERE emp.GroupId = tbl.TmpGroupId
			)
			AND ISNULL(@EmployeeId, emp.EmpId) = emp.EmpId
			AND ISNULL(@IsLocal, empSum.IsLocal) = empSum.IsLocal
			AND (
				DATENAME(DW, empC.WorkDate) = 'Saturday'
				OR DATENAME(DW, empC.WorkDate) = 'Sunday'
				)
			AND empC.IsLeaveDay != 0
			AND (
				empC.LeaveTypeId = 2
				OR empC.LeaveTypeId = 25
				OR empC.LeaveTypeId2 = 2
				OR empC.LeaveTypeId2 = 25
				)
			AND empC.WorkDate BETWEEN @FromDate
				AND @ToDate
			AND (
				@LeaveTypeId = - 1
				OR empC.LeaveTypeId = @LeaveTypeId
				OR empC.LeaveTypeId2 = @LeaveTypeId
				)
		
		UNION
		-- #general day & # half day
		SELECT emp.EmpId AS EmployeeId
			,emp.NickName
			,emp.FullName
			,emp.Code
			,empSum.IsLocal
			,gr.GroupId AS TeamId
			,gr.[Name] AS TeamName
			,gr.Code AS TeamCode
			,empC.WorkDate AS LeaveDate
			,ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) AS LeaveTypeId
			,lt.NAME AS LeaveType
			,empC.LeaveDay
			,rq.Remark
			,rq.ApproverComment
		FROM dbo.Employee AS emp WITH (NOLOCK)
			INNER JOIN #tblEmployeeId AS em ON emp.EmpId = em.EmpId
			INNER JOIN (
			SELECT *
			FROM dbo.EmployeeCalendar WITH (NOLOCK)
			WHERE (
					@EmployeeId = EmpId
					OR @EmployeeId IS NULL
					)
				AND (
					DATENAME(DW, WorkDate) = 'Saturday'
					OR DATENAME(DW, WorkDate) = 'Sunday'
					)
				AND IsLeaveDay <> 0
				AND LeaveDay <> 0.5
				AND (
					LeaveTypeId = 2
					OR LeaveTypeId = 25
					OR LeaveTypeId2 = 2
					OR LeaveTypeId2 = 25
					)
				AND WorkDate BETWEEN @FromDate
					AND @ToDate
			) AS empC ON empC.EmpId = emp.EmpId
			INNER JOIN dbo.EmployeeSummary AS empSum WITH (NOLOCK) ON empSum.EmpId = emp.EmpId
			INNER JOIN dbo.LeaveType AS lt WITH (NOLOCK) ON ISNULL(empC.LeaveTypeId, empC.LeaveTypeId2) = lt.LeaveTypeId
			INNER JOIN dbo.LeaveRequest AS le WITH (NOLOCK) ON le.EmpId = empC.EmpId
			AND empC.WorkDate BETWEEN le.FromDate
				AND le.ToDate
			AND le.LeaveType <> 0
			INNER JOIN [dbo].[WorkingTimeRequest] AS rq WITH (NOLOCK) ON le.[RequestId] = rq.[RequestId]
			AND rq.CurrentStatus IN (4, 6)
			LEFT JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
		WHERE emp.[Enabled] = 1
			AND ISNULL(emp.IsDeleted, 0) = 0
			AND EXISTS (
			SELECT 1
			FROM #tblGroupIds AS tbl
			WHERE emp.GroupId = tbl.TmpGroupId
			)
			AND ISNULL(@EmployeeId, emp.EmpId) = emp.EmpId
			AND ISNULL(@IsLocal, empSum.IsLocal) = empSum.IsLocal
			AND (
				DATENAME(DW, empC.WorkDate) = 'Saturday'
				OR DATENAME(DW, empC.WorkDate) = 'Sunday'
				)
			AND empC.IsLeaveDay <> 0
			AND empC.LeaveDay <> 0.5
			AND (
				empC.LeaveTypeId = 2
				OR empC.LeaveTypeId = 25
				OR empC.LeaveTypeId2 = 2
				OR empC.LeaveTypeId2 = 25
				)
			AND empC.WorkDate BETWEEN @FromDate
				AND @ToDate
			AND (
				@LeaveTypeId = - 1
				OR empC.LeaveTypeId = @LeaveTypeId
				OR empC.LeaveTypeId2 = @LeaveTypeId
				)
		) a
	ORDER BY LeaveDate DESC

	DROP TABLE #tblGroupIds
END
GO
/****** Object:  StoredProcedure [dbo].[Report_GetWeekendLeaveSummary]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Report_GetWeekendLeaveSummary] 
	 @FromDate DATE
	,@ToDate DATE
	,@TeamId VARCHAR(MAX) = ''
	,@EmployeeId INT = NULL
	,@IsLocal BIT = NULL
	,@MinTotalLeave INT = NULL
	,@SupervisorId INT = NULL
AS

BEGIN
	SET NOCOUNT ON;

	CREATE TABLE #tblGroupIds (TmpGroupId INT)

	IF ISNULL(@TeamId, '') <> ''
	BEGIN
		INSERT INTO #tblGroupIds (TmpGroupId)
		SELECT DISTINCT val
		FROM fnc_strSplit(@TeamId, ',')
	END

	CREATE TABLE #tblEmployeeId (EmpId INT)

	IF (@EmployeeId IS NULL)
	BEGIN
		INSERT INTO #tblEmployeeId (EmpId)
		SELECT DISTINCT EmpId
		FROM [dbo].[fnc_GetEmployeeByActorId](@SupervisorId, 1, 0)
	END
	ELSE
	BEGIN
		INSERT INTO #tblEmployeeId (EmpId)
		VALUES (@EmployeeId)
	END

	CREATE TABLE #tblWeekendLeaveSummary (
			EmpId INT
			, TotalWeekendLeaveDays FLOAT
			)

	INSERT INTO #tblWeekendLeaveSummary (
		EmpId
		, TotalWeekendLeaveDays)
	SELECT c.EmpId 
		,SUM(c.LeaveDay)
	FROM [dbo].[EmployeeCalendar] as c WITH (NOLOCK)
	INNER JOIN #tblEmployeeId AS emp ON c.EmpId = emp.EmpId
	WHERE (DATENAME(DW, c.WorkDate) = 'Saturday' OR DATENAME(DW, c.WorkDate) = 'Sunday')
		and c.IsLeaveDay != 0
		and (c.LeaveTypeId =2 or c.LeaveTypeId = 25 or c.LeaveTypeId2 = 2 or c.LeaveTypeId2 = 25)
		and (c.WorkDate between @FromDate and @ToDate)

	GROUP BY c.EmpId

	SELECT 
		emp.EmpId AS EmployeeId
		,emp.NickName
		,emp.FullName
		,emp.Code
		,empSum.IsLocal
		,wl.TotalWeekendLeaveDays as TotalWeekendLeave
		,gr.GroupId AS TeamId
		,gr.[Name] AS TeamName
		,gr.Code AS TeamCode
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN #tblWeekendLeaveSummary AS wl WITH (NOLOCK) ON wl.EmpId = emp.EmpId
		INNER JOIN dbo.EmployeeSummary AS empSum WITH (NOLOCK) ON empSum.EmpId = emp.EmpId
		LEFT JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
	WHERE emp.[Enabled] = 1
		AND wl.TotalWeekendLeaveDays >= @MinTotalLeave
		AND ISNULL(emp.IsDeleted, 0) = 0
		AND EXISTS (
			SELECT 1
			FROM #tblGroupIds AS tbl
			WHERE emp.GroupId = tbl.TmpGroupId
			)
		AND ISNULL(@EmployeeId, emp.EmpId) = emp.EmpId
		AND ISNULL(@IsLocal, empSum.IsLocal) = empSum.IsLocal

	ORDER BY gr.[Name] ASC
		,emp.Code ASC

	DROP TABLE #tblWeekendLeaveSummary

	DROP TABLE #tblGroupIds
END

GO
/****** Object:  StoredProcedure [dbo].[Report_LeaveSummary]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Report_LeaveSummary] @empid INT = NULL
	,@TeamIds VARCHAR(max) = ''
	,@year INT
	,@isLocal BIT = NULL
	,@SupervisorId INT = NULL
	,@role VARCHAR(max) = ''
AS
/*
Created: Tom.Vo@2013-11-21
Task: leave summary report
DB: HRM_SMS
Original:

Revisions:
Param's Explanation:
*/
BEGIN
	SET NOCOUNT ON;

	DECLARE
		-- keep in view type
		@KeepInViewByDay TINYINT = 1

	CREATE TABLE #DeductKIV (
		EmpId INT
		,WorkDate DATETIME
		,DeductDays DECIMAL(18, 12)
		)

	CREATE TABLE #tmpOwner (OwnerId INT)

	CREATE TABLE #GroupsList (GroupId INT)

	CREATE TABLE #EmployeeId (EmpId INT)

	IF ISNULL(@TeamIds, '') <> ''
	BEGIN
		INSERT INTO #GroupsList (GroupId)
		SELECT val
		FROM fnc_strSplit(@TeamIds, ',')
	END

	--ELSE
	--BEGIN
	--	IF EXISTS (
	--			SELECT 1
	--			FROM dbo.Employee AS e WITH (NOLOCK)
	--				INNER JOIN dbo.EmployeeRole AS er WITH (NOLOCK) ON e.EmpId = er.EmployeeId
	--			WHERE EmpId = @SupervisorId
	--				AND er.RoleId IN (2, 3, 4, 5, 6, 7)
	--			)
	--	BEGIN
	--		INSERT INTO #GroupsList (GroupId)
	--		SELECT GroupId
	--		FROM dbo.[Group] WITH (NOLOCK)
	--	END
	--END
	IF @empid IS NULL
	BEGIN
		INSERT INTO #EmployeeId (EmpId)
		SELECT EmpId
		FROM dbo.fnc_GetEmployeeByActorId(@SupervisorId, 1, 0)
	END
	ELSE
	BEGIN
		INSERT INTO #EmployeeId (EmpId)
		VALUES (@empid)
	END

	DECLARE @fromdate DATETIME
		,@todate DATETIME

	-- get the first date of year
	SET @fromdate = cast(@year AS VARCHAR(10)) + '/01/01'
	SET @todate = DATEADD(yy, 1, @fromdate)

	-- get the openning balace for annual leave to first date of year
	SELECT e.EmpId AS Empid
		,SUM(ISNULL(CreditDays, 0) - ISNULL(DeductDays, 0)) AS OpenBalance
	INTO #OpenBalance
	FROM dbo.Employee AS e WITH (NOLOCK)
		LEFT JOIN dbo.EmployeeSummary AS es WITH (NOLOCK) ON e.EmpId = es.EmpId
		LEFT JOIN (
		SELECT *
		FROM dbo.LeaveTrans WITH (NOLOCK)
		WHERE ISNULL(Deleted, 0) = 0
			AND FromDate <= @fromdate
		) t ON e.EmpId = t.Empid
	WHERE EXISTS (
			SELECT 1
			FROM #EmployeeId
			WHERE e.EmpId = EmpId
			)
		AND (
			@isLocal IS NULL
			OR es.IsLocal = @isLocal
			)
		AND (
			--@Teamids IS NULL OR
			--@Teamids = '' OR
			e.GroupId IN (
				SELECT GroupId
				FROM #GroupsList
				)
			)
		AND (
			ISNULL(e.isDeleted, 0) = 0
			OR YEAR(ResignedDate) >= year(@todate)
			)
	GROUP BY e.EmpId

	SELECT w.EmpId AS EmpId
		,SUM(CASE 
				WHEN kiv.IsHalfDay = 1 THEN 0.5
				ELSE 1
				END) AS OpenKIV
	INTO #CreditKIV
	FROM dbo.WorkingTimeRequest AS w WITH (NOLOCK)
		INNER JOIN dbo.KeepInViewRequest AS kiv WITH (NOLOCK) ON w.RequestId = kiv.RequestId
		AND kiv.OnDate BETWEEN @fromdate
			AND @todate
	WHERE w.CurrentStatus IN (4, 6)
		AND kiv.KeepInViewType = @KeepInViewByDay
	GROUP BY w.EmpId

	-- KIV leave
	INSERT #DeductKIV (
		EmpId
		,WorkDate
		,DeductDays
		)
	SELECT cl.EmpId AS EmpId
		,cl.WorkDate AS WorkDate
		,CAST((CASE 
				WHEN rq.TotalDays > 1 THEN 1
				ELSE rq.TotalDays END
				) AS DECIMAL(18, 2)) AS DeductDays
	FROM dbo.EmployeeCalendar AS cl WITH (NOLOCK)
		LEFT JOIN (
		SELECT w.RequestId
			,w.EmpId
			,w.CurrentStatus
			,lv.FromDate
			,lv.ToDate
			,lv.TotalDays
			,lv.LeaveType
		FROM dbo.LeaveRequest AS lv WITH (NOLOCK)
			INNER JOIN dbo.WorkingTimeRequest AS w WITH (NOLOCK) ON lv.RequestId = w.RequestId
		WHERE lv.LeaveType = 10
		) AS rq ON cl.EmpId = rq.EmpId
		AND cl.WorkDate BETWEEN rq.FromDate
			AND rq.ToDate
	WHERE EXISTS (
			SELECT 1
			FROM #EmployeeId
			WHERE EmpId = cl.EmpId
			)
		AND cl.IsLeaveDay = 1
		AND cl.WorkDate BETWEEN rq.FromDate
			AND rq.ToDate
		AND rq.CurrentStatus IN (4, 6)
		AND cl.WorkDate BETWEEN @fromdate
			AND DATEADD(dd, - 1, @todate)

	-- General leave
	INSERT #DeductKIV (
		EmpId
		,WorkDate
		,DeductDays
		)
	SELECT ldt.EmpId
		,ldt.OnDate AS WorkDate
		,CAST((CASE 
				WHEN IsHalfDay = 1 THEN 0.5
				ELSE 1 END
				) AS DECIMAL(18, 2)) AS DeductDays
	FROM dbo.LeaveRequestDetail AS ldt WITH (NOLOCK)
		INNER JOIN dbo.LeaveRequest AS lv WITH (NOLOCK) ON ldt.RequestId = lv.RequestId
		INNER JOIN dbo.WorkingTimeRequest AS w WITH (NOLOCK) ON ldt.RequestId = w.RequestId
	WHERE ldt.LeaveType = 10
		AND lv.LeaveType = 0
		AND w.CurrentStatus IN (4, 6)
		AND ldt.OnDate BETWEEN @fromdate
			AND DATEADD(dd, - 1, @todate)
		AND EXISTS (
			SELECT 1
			FROM #EmployeeId
			WHERE EmpId = ldt.EmpId
			)

	SELECT EmpId
		,SUM(DeductDays) AS DeductKIVDays
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 1 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Jan
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 2 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Feb
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 3 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Mar
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 4 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Apr
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 5 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS May
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 6 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Jun
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 7 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Jul
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 8 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Aug
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 9 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Sep
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 10 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Oct
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 11 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS Nov
		,SUM(CASE 
				WHEN MONTH(WorkDate) = 12 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) AS [Dec]
	INTO #CurrentKIV
	FROM #DeductKIV
	GROUP BY EmpId

	-- calculate the balance form the first date of year to @todate
	SELECT e.EmpId
		,(ISNULL(CreditDays, 0)) CreditDays
		,SUM(ISNULL(DeductDays, 0)) DeductDays
		,SUM(CASE 
				WHEN MONTH(FromDate) = 1 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Jan
		,SUM(CASE 
				WHEN MONTH(FromDate) = 2 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Feb
		,SUM(CASE 
				WHEN MONTH(FromDate) = 3 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Mar
		,SUM(CASE 
				WHEN MONTH(FromDate) = 4 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Apr
		,SUM(CASE 
				WHEN MONTH(FromDate) = 5 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) May
		,SUM(CASE 
				WHEN MONTH(FromDate) = 6 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Jun
		,SUM(CASE 
				WHEN MONTH(FromDate) = 7 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Jul
		,SUM(CASE 
				WHEN MONTH(FromDate) = 8 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Aug
		,SUM(CASE 
				WHEN MONTH(FromDate) = 9 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Sep
		,SUM(CASE 
				WHEN MONTH(FromDate) = 10 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Oct
		,SUM(CASE 
				WHEN MONTH(FromDate) = 11 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) Nov
		,SUM(CASE 
				WHEN MONTH(FromDate) = 12 THEN ISNULL(DeductDays, 0)
				ELSE 0
				END) DEC
	INTO #CurrenBalace
	FROM dbo.Employee AS e WITH (NOLOCK)
		LEFT JOIN (
		SELECT EmpId
			,DeductDays
			,FromDate
		FROM dbo.LeaveTrans WITH (NOLOCK)
		WHERE YEAR(FromDate) = @year
			AND ISNULL(Deleted, 0) = 0
		) AS ded ON e.EmpId = ded.EmpId
		LEFT JOIN (
		SELECT lt.EmpId
			,SUM(CreditDays) CreditDays
		FROM dbo.LeaveTrans AS lt WITH (NOLOCK)
		WHERE FromDate >= @fromdate
			AND FromDate < @todate
			AND ISNULL(Deleted, 0) <> 1
			AND CreditDays > 0
			AND ISNULL(Deleted, 0) <> 1
		GROUP BY lt.EmpId
		) Cred ON e.EmpId = Cred.Empid
		LEFT JOIN EmployeeSummary es WITH (NOLOCK) ON e.EmpId = es.EmpId
	WHERE EXISTS (
			SELECT 1
			FROM #EmployeeId
			WHERE e.EmpId = EmpId
			)
		AND (
			@isLocal IS NULL
			OR es.IsLocal = @isLocal
			)
		AND (
			--@Teamids IS NULL OR
			--@Teamids = '' OR
			e.GroupId IN (
				SELECT GroupId
				FROM #GroupsList
				)
			)
		AND (
			ISNULL(e.isDeleted, 0) = 0
			OR YEAR(ResignedDate) >= year(@todate)
			)
	GROUP BY e.EmpId
		,(ISNULL(CreditDays, 0))

	-- show the report
	SELECT ISNULL(OpenKIV, 0) AS CreditKIV
		,ISNULL(OpenBalance, 0) AS [AnnualLeaveLastYear]
		,ISNULL(CreditDays, 0) AS [AnnualLeaveCurrentYear]
		,(cb.Jan + ISNULL(dek.Jan, 0)) AS Jan
		,(cb.Feb + ISNULL(dek.Feb, 0)) AS Feb
		,(cb.Mar + ISNULL(dek.Mar, 0)) AS Mar
		,(cb.Apr + ISNULL(dek.Apr, 0)) AS Apr
		,(cb.May + ISNULL(dek.May, 0)) AS May
		,(cb.Jun + ISNULL(dek.Jun, 0)) AS Jun
		,(cb.Jul + ISNULL(dek.Jul, 0)) AS Jul
		,(cb.Aug + ISNULL(dek.Aug, 0)) AS Aug
		,(cb.Sep + ISNULL(dek.Sep, 0)) AS Sep
		,(cb.Oct + ISNULL(dek.Oct, 0)) AS Oct
		,(cb.Nov + ISNULL(dek.Nov, 0)) AS Nov
		,(cb.[Dec] + ISNULL(dek.[Dec], 0)) AS [Dec]
		,ISNULL(CreditDays, 0) - ISNULL(cb.DeductDays, 0) AS LeaveBalance
		,ISNULL(OpenKIV, 0) - ISNULL(dek.DeductKIVDays, 0) AS KIVBalance
		,'' AS Remark
		,cb.EmpId
		,e.Code
		,FullName
		,Email
		,NickName
		,g.[Rank]
		,g.GroupId AS TeamId
		,g.[Name] AS Team
		,sec.Code AS Section
		,dep.Code AS Department
	FROM #CurrenBalace AS cb
		LEFT JOIN #OpenBalance AS op ON OP.empid = cb.empid
		LEFT JOIN #CreditKIV AS crk ON cb.EmpId = crk.EmpId
		LEFT JOIN #CurrentKIV AS dek ON cb.EmpId = dek.EmpId
		INNER JOIN dbo.Employee AS e WITH (NOLOCK) ON e.EmpId = cb.Empid
		LEFT JOIN dbo.EmployeeSummary AS es WITH (NOLOCK) ON e.EmpId = es.EmpId
		LEFT JOIN dbo.[Group] AS g WITH (NOLOCK) ON g.GroupId = e.GroupId
		INNER JOIN dbo.Section AS sec WITH (NOLOCK) ON sec.SectionId = g.SectionId
		INNER JOIN dbo.Department AS dep WITH (NOLOCK) ON dep.DepartmentId = sec.DepartmentId
	WHERE ISNULL(e.[Enabled], 0) = 1
		AND (
			@isLocal IS NULL
			OR es.IsLocal = @isLocal
			)
	
	UNION ALL
	SELECT ISNULL(OpenKIV, 0) AS CreditKIV
		,ISNULL(OpenBalance, 0) [AnnualLeaveLastYear]
		,0 AS [AnnualLeaveCurrentYear]
		,dek.Jan
		,dek.Feb
		,dek.Mar
		,dek.Apr
		,dek.May
		,dek.Jun
		,dek.Jul
		,dek.Aug
		,dek.Sep
		,dek.Oct
		,dek.Nov
		,dek.[Dec]
		,ISNULL(OpenBalance, 0) AS LeaveBalance
		,ISNULL(OpenKIV, 0) - ISNULL(dek.DeductKIVDays, 0) AS KIVBalance
		,'' AS Remark
		,op.EmpId
		,e.[Code]
		,FullName
		,Email
		,NickName
		,g.[Rank]
		,g.GroupId AS TeamId
		,g.[Name] AS Team
		,sec.Code AS Section
		,dep.Code AS Department
	FROM #OpenBalance AS op
		LEFT JOIN #CreditKIV AS kiv ON op.EmpId = kiv.EmpId
		LEFT JOIN #CurrentKIV AS dek ON op.EmpId = dek.EmpId
		INNER JOIN dbo.Employee AS e WITH (NOLOCK) ON e.Empid = op.Empid
		LEFT JOIN dbo.EmployeeSummary AS es WITH (NOLOCK) ON e.EmpId = es.EmpId
		LEFT JOIN dbo.[Group] AS g WITH (NOLOCK) ON g.GroupId = e.GroupId
		INNER JOIN dbo.Section AS sec WITH (NOLOCK) ON sec.SectionId = g.SectionId
		INNER JOIN dbo.Department AS dep WITH (NOLOCK) ON dep.DepartmentId = sec.DepartmentId
	WHERE e.Empid NOT IN (
			SELECT EmpID
			FROM #CurrenBalace AS cb
			)
		AND ISNULL(e.[Enabled], 0) = 1
		AND (
			@isLocal IS NULL
			OR es.IsLocal = @isLocal
			)
	ORDER BY g.[Name]
		,e.[Code]

	DROP TABLE #OpenBalance

	DROP TABLE #CurrenBalace

	DROP TABLE #CreditKIV

	DROP TABLE #DeductKIV

	DROP TABLE #CurrentKIV

	DROP TABLE #GroupsList
END

