CREATE PROCEDURE [dbo].[ScheduleArrangement_GetWeekly] @ActorId INT
	,@fromtime DATE
	,@totime DATE
	,@EmpId INT = NULL
	,@TeamIds VARCHAR(MAX) = ''
	,@IsIFrame BIT = 0
	,@isLocal BIT = NULL
AS
/*
Created: Tim.Trinh@2019-04-12
Task: Get weekly schedules
DB: HRM
Original:

Revisions:
Param's Explanation:

*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @Today DATE = GETDATE()
		,@EmployeeIds VARCHAR(MAX)
		,@EditScheduleUnlimited VARCHAR(100) = 'EditScheduleUnlimited'
		,@ShiftManagerRoleId TINYINT = 4
		,@GeneralLeaveId TINYINT = 0
		,@OffDayShiftId SMALLINT = - 1
		-- request status
		,@NotVerifiedStatusId TINYINT = 3
		,@RejectedStatusId TINYINT = 5
		,@VoidStatusId TINYINT = 7
	DECLARE @tblGroupIds TABLE (GroupId INT)
	DECLARE @tblDefaultShift TABLE (
		EmployeeId INT
		,ShiftId INT
		)
	CREATE TABLE #tblEmployeeIds (EmpId INT)

	IF ISNULL(@TeamIds, '') <> ''
	BEGIN
		INSERT INTO @tblGroupIds (GroupId)
		SELECT val
		FROM dbo.fnc_strSplit(@TeamIds, ',')
	END

	INSERT INTO #tblEmployeeIds (EmpId)
	SELECT OwnerId
	FROM dbo.EmployeeSupervisor AS es WITH (NOLOCK)
	WHERE EmpId = @ActorId
		AND (
			@EmpId IS NULL
			OR es.OwnerId = @EmpId
			)
		AND ActionType = @ShiftManagerRoleId
		AND ISNULL(IsDeleted, 0) = 0
		AND EXISTS (
			SELECT 1
			FROM dbo.Employee AS emp WITH (NOLOCK)
				INNER JOIN @tblGroupIds AS gr ON emp.GroupId = gr.GroupId
			WHERE emp.[Enabled] = 1
				AND emp.isDeleted = 0
				AND es.OwnerId = emp.EmpId
			)

	INSERT INTO #tblEmployeeIds (EmpId)
	SELECT emp.EmpId
	FROM dbo.GroupSupervisor AS gs WITH (NOLOCK)
		INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON gs.GroupId = emp.GroupId
	WHERE gs.OwnerId = @ActorId
		AND gs.ActionType = @ShiftManagerRoleId
		AND ISNULL(gs.IsDeleted, 0) = 0
		AND emp.[Enabled] = 1
		AND emp.isDeleted = 0
		AND (
			@EmpId IS NULL
			OR emp.EmpId = @EmpId
			)
		AND EXISTS (
			SELECT 1
			FROM @tblGroupIds AS gr
			WHERE emp.GroupId = gr.GroupId
			)
		AND NOT EXISTS (
			SELECT 1
			FROM #tblEmployeeIds AS tbl WITH (NOLOCK)
			WHERE tbl.EmpId = emp.EmpId
			)

	IF @IsIFrame = 1
		OR EXISTS (
			SELECT 1
			FROM dbo.RoleFunction AS rf WITH (NOLOCK)
				INNER JOIN dbo.[Function] AS f WITH (NOLOCK) ON rf.FunctionId = f.FunctionId
				AND f.FunctionKey = @EditScheduleUnlimited
				AND f.IsActive = 1
				INNER JOIN dbo.EmployeeRole AS erole WITH (NOLOCK) ON rf.RoleId = erole.RoleId
				AND erole.EmployeeId = @ActorId
			WHERE rf.IsRead = 1 OR rf.IsHost = 1
			)
	BEGIN
		INSERT INTO #tblEmployeeIds (EmpId)
		SELECT EmpId
		FROM dbo.Employee AS emp WITH (NOLOCK)
		WHERE [Enabled] = 1
			AND isDeleted = 0
			AND (
				@EmpId IS NULL
				OR emp.EmpId = @EmpId
				)
			AND EXISTS (
				SELECT 1
				FROM @tblGroupIds AS gr
				WHERE emp.GroupId = gr.GroupId
				)
			AND NOT EXISTS (
				SELECT 1
				FROM #tblEmployeeIds AS tbl WITH (NOLOCK)
				WHERE emp.EmpId = tbl.EmpId
				)
	END

	DELETE emp
	FROM #tblEmployeeIds AS emp
	WHERE EXISTS (
			SELECT 1
			FROM dbo.EmployeeSummary AS esum WITH (NOLOCK)
			WHERE emp.EmpId = esum.EmpId
				AND esum.IsTopManager = 1
			)

	SELECT @EmployeeIds = COALESCE(@EmployeeIds + ',', '') + CAST(EmpId AS VARCHAR(10))
	FROM #tblEmployeeIds WITH (NOLOCK)

	EXEC dbo.tmpEmployeeCalendar_Insert @fromDate = @fromtime
		,@toDate = @totime
		,@empIds = @EmployeeIds
		,@isEnable = 1
		,@isDelete = 0

	SELECT emp.EmpId
		,tmpca.WorkDate
		,tmpca.ShiftId
		,tmpca.IsOvertime
		,tmpca.IsOffDay
		,tmpca.IsHoliday
		,tmpca.IsKeepInView
		,tmpca.IsLeaveOffDay
		,tmpca.IsLeaveDay
		,tmpca.LeaveTypeId
		,tmpca.FromTime
		,tmpca.ToTime
		,tmpca.LeaveTypeId2
		,tmpca.LeaveDay
		,empca.IsFixedOffDay
		,empca.IsPublic
		,empca.ModifiedBy
		,empca.ModifiedDate
		,(CASE 
			WHEN offrep.EmployeeId IS NOT NULL THEN 1
			ELSE 0 END
			) AS IsOffDayReplacement
		,tmpca.ChangeShiftTypeId
		,tmpca.MoveOffFromDate
		,tmpca.MoveOffToDate
	INTO #tblEmployeeCalendar
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN dbo.tmpEmployeeCalendar AS tmpca WITH (NOLOCK) ON emp.EmpId = tmpca.EmpId
		AND tmpca.WorkDate BETWEEN @fromTime
			AND @toTime
		INNER JOIN #tblEmployeeIds AS tblemp WITH (NOLOCK) ON emp.EmpId = tblemp.EmpId
		LEFT JOIN dbo.EmployeeCalendar AS empca WITH (NOLOCK) ON emp.EmpId = empca.EmpId
		AND tmpca.WorkDate = empca.WorkDate
		LEFT JOIN dbo.ScheduleArrangementOffDayReplacement AS offrep WITH (NOLOCK) ON emp.EmpId = offrep.EmployeeId
		AND tmpca.WorkDate = offrep.WorkDate
	WHERE @IsIFrame = 0
		OR (
			@IsIFrame = 1
			AND ISNULL(empca.IsPublic, 0) = 1
			)

	IF @IsIFrame = 1
	BEGIN
		DELETE emp
		FROM #tblEmployeeIds AS emp WITH (NOLOCK)
		WHERE NOT EXISTS (
				SELECT 1
				FROM #tblEmployeeCalendar AS empca WITH (NOLOCK)
				WHERE emp.EmpId = empca.EmpId
				)
	END

	INSERT INTO @tblDefaultShift (
		EmployeeId
		,ShiftId
		)
	SELECT emp.EmpId
		,defaultshift.ShiftId
	FROM #tblEmployeeIds AS emp WITH (NOLOCK)
		INNER JOIN dbo.ScheduleArrangementDefaultShift AS defaultshift WITH (NOLOCK) ON emp.EmpId = defaultshift.EmployeeId
	WHERE defaultshift.FromDate = @fromtime

	INSERT INTO @tblDefaultShift (
		EmployeeId
		,ShiftId
		)
	SELECT data.EmployeeId
		,defaultshift.ShiftId
	FROM (
		SELECT EmployeeId
			,MAX(FromDate) AS FromDate
		FROM dbo.ScheduleArrangementDefaultShift WITH (NOLOCK)
		WHERE FromDate < @fromtime
		GROUP BY EmployeeId
		) data
		INNER JOIN dbo.ScheduleArrangementDefaultShift AS defaultshift WITH (NOLOCK) ON data.EmployeeId = defaultshift.EmployeeId
		AND data.FromDate = defaultshift.FromDate
	WHERE NOT EXISTS (
			SELECT 1
			FROM @tblDefaultShift AS tbl
			WHERE defaultshift.EmployeeId = tbl.EmployeeId
			)

	SELECT emp.EmpId AS EmployeeId
		,emp.Code
		,emp.NickName
		,emp.FullName
		,ISNULL(esum.OffDaysbyWeek, 0) AS OffDaysbyWeek
		,emp.PickupRemark
		,arrange.Remark
		,arrange.DisplayOrder
		,esum.IsDefaultSchedule AS IsUsedWeeklyDefaultShift
		,modifier.NickName AS Modifier
		,ec.ModifiedDate
		,gr.GroupId AS TeamId
		,gr.Code
		,gr.[Name]
		,shift.ShiftId AS DefaultShiftId
		,shift.Code
		,shift.[Name]
		,shift.BeginCheckInTime AS CheckIn
		,shift.BeginCheckOutTime AS CheckOut
		,shift.IsInAfterDay
		,shift.IsOutAfterDay
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN #tblEmployeeIds AS tblemp WITH (NOLOCK) ON emp.EmpId = tblemp.EmpId
		LEFT JOIN dbo.EmployeeSummary AS esum WITH (NOLOCK) ON emp.EmpId = esum.EmpId
		LEFT JOIN dbo.[Group] AS gr WITH (NOLOCK) ON emp.GroupId = gr.GroupId
		LEFT JOIN dbo.ScheduleArrangement AS arrange WITH (NOLOCK) ON emp.EmpId = arrange.EmployeeId
		LEFT JOIN dbo.ScheduleArrangementGroupOrder AS gorder WITH (NOLOCK) ON gr.GroupId = gorder.GroupId
		LEFT JOIN @tblDefaultShift AS defaultshift ON emp.EmpId = defaultshift.EmployeeId
		LEFT JOIN dbo.Shift AS shift WITH (NOLOCK) ON defaultshift.ShiftId = shift.ShiftId
		AND ISNULL(shift.IsDisabled, 0) = 0
		OUTER APPLY (
		SELECT TOP 1 ec.ModifiedBy
			,ec.ModifiedDate
		FROM #tblEmployeeCalendar AS ec
		WHERE ec.EmpId = emp.EmpId
			AND ec.ModifiedBy IS NOT NULL
			AND ec.ModifiedDate IS NOT NULL
			AND ec.ModifiedDate = (
				SELECT MAX(ec1.ModifiedDate)
				FROM #tblEmployeeCalendar AS ec1 WITH (NOLOCK)
				WHERE ec.EmpId = ec1.EmpId
				)
		) AS ec
		LEFT JOIN dbo.Employee AS modifier WITH (NOLOCK) ON ec.ModifiedBy = modifier.EmpId
	WHERE EXISTS (
			SELECT 1
			FROM @tblGroupIds AS tblgr
			WHERE emp.GroupId = tblgr.GroupId
			)
			AND (
			@isLocal IS NULL
			OR esum.IsLocal = @isLocal
			)
	ORDER BY ISNULL(gorder.DisplayOrder, 0)
		,gr.Code
		,ISNULL(arrange.DisplayOrder, 0)
		,emp.NickName

	SELECT emp.EmpId AS EmployeeId
		,empca.WorkDate
		,empca.IsOvertime
		,empca.IsLeaveOffDay
		,empca.ChangeShiftTypeId
		,empca.MoveOffFromDate
		,empca.MoveOffToDate
		,empca.IsHoliday
		,empca.IsOffDay
		,empca.IsFixedOffDay
		,empca.IsLeaveDay
		,empca.IsKeepInView
		,empca.LeaveDay
		,empca.IsPublic
		,empca.IsOffDayReplacement
		,(CASE 
			WHEN empca.ModifiedBy IS NOT NULL THEN 1
			WHEN @fromTime <= @Today THEN 1
			ELSE 0 END
			) AS IsModified
		,shift.ShiftId
		,shift.Code
		,shift.[Name]
		,shift.BeginCheckInTime AS CheckIn
		,shift.BeginCheckOutTime AS CheckOut
		,shift.IsInAfterDay
		,shift.IsOutAfterDay
		,lv1.LeaveTypeId
		,lv1.Code
		,lv1.[Name]
		,empca.FromTime
		,empca.ToTime
		,lv2.LeaveTypeId AS LeaveTypeId2
		,lv2.Code
		,lv2.[Name]
	FROM dbo.Employee AS emp WITH (NOLOCK)
		INNER JOIN #tblEmployeeIds AS tblemp WITH (NOLOCK) ON emp.EmpId = tblemp.EmpId
		INNER JOIN #tblEmployeeCalendar AS empca ON emp.EmpId = empca.EmpId
		AND empca.WorkDate BETWEEN @fromTime
			AND @toTime
		LEFT JOIN dbo.Shift AS shift WITH (NOLOCK) ON shift.ShiftId = empca.ShiftId
		LEFT JOIN dbo.LeaveType AS lv1 WITH (NOLOCK) ON empca.LeaveTypeId = lv1.LeaveTypeId
		LEFT JOIN dbo.LeaveType AS lv2 WITH (NOLOCK) ON empca.LeaveTypeId2 = lv2.LeaveTypeId
	WHERE EXISTS (
			SELECT 1
			FROM @tblGroupIds AS tblgr
			WHERE emp.GroupId = tblgr.GroupId
			)
	ORDER BY emp.NickName
		,empca.WorkDate

	SELECT emp.EmpId AS EmployeeId
		,ISNULL(monshift.ShiftId, @OffDayShiftId) AS MonShiftId
		,ISNULL(tueshift.ShiftId, @OffDayShiftId) AS TueShiftId
		,ISNULL(wedshift.ShiftId, @OffDayShiftId) AS WedShiftId
		,ISNULL(thushift.ShiftId, @OffDayShiftId) AS ThuShiftId
		,ISNULL(frishift.ShiftId, @OffDayShiftId) AS FriShiftId
		,ISNULL(satshift.ShiftId, @OffDayShiftId) AS SatShiftId
		,ISNULL(sunshift.ShiftId, @OffDayShiftId) AS SunShiftId
	FROM #tblEmployeeIds AS emp WITH (NOLOCK)
		LEFT JOIN dbo.EmployeeDefaultShift AS eds WITH (NOLOCK) ON eds.EmpId = emp.EmpId
		LEFT JOIN dbo.Shift AS monshift WITH (NOLOCK) ON eds.MonShift = monshift.ShiftId
		AND ISNULL(monshift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS tueshift WITH (NOLOCK) ON eds.TueShift = tueshift.ShiftId
		AND ISNULL(tueshift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS wedshift WITH (NOLOCK) ON eds.WedShift = wedshift.ShiftId
		AND ISNULL(wedshift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS thushift WITH (NOLOCK) ON eds.ThuShift = thushift.ShiftId
		AND ISNULL(thushift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS frishift WITH (NOLOCK) ON eds.FriShift = frishift.ShiftId
		AND ISNULL(frishift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS satshift WITH (NOLOCK) ON eds.SatShift = satshift.ShiftId
		AND ISNULL(satshift.IsDisabled, 0) = 0
		LEFT JOIN dbo.Shift AS sunshift WITH (NOLOCK) ON eds.SunShift = sunshift.ShiftId
		AND ISNULL(sunshift.IsDisabled, 0) = 0

	DROP TABLE #tblEmployeeIds
	DROP TABLE #tblEmployeeCalendar
END


GO
/****** Object:  StoredProcedure [dbo].[ScheduleArrangement_SyncWorkingShift]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ScheduleArrangement_SyncWorkingShift] @ActorId INT
	,@FromDate DATE
	,@ToDate DATE
	,@EmployeeIds NVARCHAR(MAX) = ''
	,@WorkingShiftXml NVARCHAR(MAX) = ''
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: 20220106@Tim.Trinh
Task: sync working shift from OWP
DB:
Original:

Revisions:
Param's Explanation:
- @WorkingShiftXml: "<Root>
		<Row EmployeeID={1} ShiftCode={2} ShiftDate={3} ShiftStartTime={4} ShiftEndTime={5} LastUpdated={6} IsOffDay={7} IsPublicHoliday={8} IsInAfterDay={9} IsOutAfterDay={10} IsCrossDay={11} TotalHours={12} />
	</Root>"
*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @SyncDate DATETIME = GETDATE()
		,@Today DATE = GETDATE()
		,@EmpId INT
		,@WorkDate DATE
		,@DocHandler INT

	CREATE TABLE #tmpWorkingShift (
		EmployeeID VARCHAR(20)
		,ShiftCode VARCHAR(20)
		,ShiftDate DATE
		,CheckInTime NCHAR(5) NULL
		,CheckOutTime NCHAR(5) NULL
		,ModifiedDate DATETIME
		,IsOffDay BIT
		,IsHoliday BIT
		,IsInAfterDay BIT
		,IsOutAfterDay BIT
		,IsCrossDay BIT
		,TotalHours DECIMAL(10, 2)
		)

	CREATE TABLE #tmpEmployeeIds (EmpId INT PRIMARY KEY)

	CREATE TABLE #tmpEmployeeCalendar (
		EmpId INT
		,WorkDate DATE
		,ShiftId INT
		,IsOffDay BIT
		,IsHoliday BIT
		)

	IF ISNULL(@EmployeeIds, '') <> ''
	BEGIN
		INSERT INTO #tmpEmployeeIds (EmpId)
		SELECT DISTINCT val
		FROM dbo.fnc_strSplit(@EmployeeIds, ',')
		WHERE ISNUMERIC(val) = 1
	END

	BEGIN TRY
	EXEC sp_xml_preparedocument @DocHandler OUTPUT
		,@WorkingShiftXml

	INSERT INTO #tmpWorkingShift (
		EmployeeID
		,ShiftCode
		,ShiftDate
		,CheckInTime
		,CheckOutTime
		,ModifiedDate
		,IsOffDay
		,IsHoliday
		,IsInAfterDay
		,IsOutAfterDay
		,IsCrossDay
		,TotalHours
		)
	SELECT EmployeeID
		,ShiftCode
		,ShiftDate
		,CASE 
			WHEN ISNULL(CheckInTime, '') = '' THEN NULL
			ELSE CheckInTime
			END
		,CASE 
			WHEN ISNULL(CheckOutTime, '') = '' THEN NULL
			ELSE CheckOutTime
			END
		,LastUpdated
		,IsOffDay
		,IsPublicHoliday
		,IsInAfterDay
		,IsOutAfterDay
		,IsCrossDay
		,TotalHours
	FROM OPENXML(@DocHandler, '/Root/Row', 1) WITH (EmployeeID VARCHAR(20), ShiftCode VARCHAR(20), ShiftDate DATE, CheckInTime NCHAR(5), CheckOutTime NCHAR(5), LastUpdated DATETIME, IsOffDay BIT, IsPublicHoliday BIT, IsInAfterDay BIT, IsOutAfterDay BIT, IsCrossDay BIT, TotalHours DECIMAL(10, 2)) AS Data

	EXEC sp_xml_removedocument @DocHandler

	INSERT INTO dbo.[Shift] (
		Code
		,[Name]
		,BeginCheckInTime
		,EndCheckInTime
		,BeginCheckOutTime
		,EndCheckOutTime
		,BreakTimeMins
		,TotalHours
		,CrossDay
		,IsInAfterDay
		,IsOutAfterDay
		,OWPModifiedDate
		,OWPSyncDate
		,CreatedDate
		,IsDisabled
		)
	SELECT tmpws.ShiftCode
		,tmpws.ShiftCode
		,tmpws.CheckInTime
		,tmpws.CheckInTime
		,tmpws.CheckOutTime
		,tmpws.CheckOutTime
		,0
		,tmpws.TotalHours
		,tmpws.IsCrossDay
		,tmpws.IsInAfterDay
		,tmpws.IsOutAfterDay
		,MAX(tmpws.ModifiedDate)
		,@SyncDate
		,@SyncDate
		,0
	FROM #tmpWorkingShift AS tmpws WITH (NOLOCK)
	WHERE tmpws.CheckInTime IS NOT NULL
		AND tmpws.CheckOutTime IS NOT NULL
		AND NOT EXISTS (
			SELECT s.ShiftID
			FROM dbo.[Shift] AS s WITH (NOLOCK)
			WHERE s.Code = tmpws.ShiftCode
			)
		AND EXISTS (
			SELECT emp.EmpId
			FROM dbo.Employee AS emp WITH (NOLOCK)
			WHERE tmpws.EmployeeID = emp.Code
			)
	GROUP BY tmpws.ShiftCode
		,tmpws.CheckInTime
		,tmpws.CheckOutTime
		,tmpws.IsInAfterDay
		,tmpws.IsOutAfterDay
		,tmpws.IsCrossDay
		,tmpws.TotalHours

	UPDATE ec
	SET ec.ShiftId = s.ShiftID
		,ec.IsOffDay = CASE 
			WHEN tmpca.IsLeaveDay = 0
				AND tmpca.IsKeepInView = 0
				AND tmpca.ChangeShiftTypeId IS NULL THEN
					CASE
						WHEN tmpws.IsOffDay = 0 AND s.ShiftID IS NULL AND ISNULL(tmpws.ShiftCode, '') != '' THEN ec.IsOffDay
						ELSE tmpws.IsOffDay END
			ELSE ec.IsOffDay
			END
		,ec.IsHoliday = CASE 
			WHEN tmpws.IsHoliday = 1
				AND h.Id IS NOT NULL THEN 1
			ELSE 0
			END
		,ec.ModifiedBy = @ActorId
		,ec.ModifiedDate = @SyncDate
		,ec.OWPSyncDate = @SyncDate
	OUTPUT INSERTED.EmpId
		,INSERTED.WorkDate
		,INSERTED.ShiftId
		,INSERTED.IsOffDay
		,INSERTED.IsHoliday
	INTO #tmpEmployeeCalendar(EmpId, WorkDate, ShiftId, IsOffDay, IsHoliday)
	FROM dbo.EmployeeCalendar AS ec WITH (ROWLOCK, UPDLOCK)
		INNER JOIN dbo.Employee AS e WITH (NOLOCK) ON ec.EmpId = e.EmpId
		INNER JOIN #tmpEmployeeIds AS tmpemp WITH (NOLOCK) ON e.EmpId = tmpemp.EmpId
		INNER JOIN #tmpWorkingShift AS tmpws WITH (NOLOCK) ON e.Code = tmpws.EmployeeID
		INNER JOIN dbo.tmpEmployeeCalendar AS tmpca WITH (NOLOCK) ON ec.EmpId = tmpca.EmpId
		AND ec.WorkDate = tmpca.WorkDate
		AND CAST(ec.WorkDate AS DATE) = CAST(tmpws.ShiftDate AS DATE)
		LEFT JOIN dbo.[Shift] AS s WITH (NOLOCK) ON s.Code = tmpws.ShiftCode
		LEFT JOIN dbo.Holiday AS h WITH (NOLOCK) ON tmpws.ShiftDate BETWEEN h.FromDate
			AND h.ToDate
	WHERE tmpca.ChangeShiftTypeId IS NULL
		AND tmpca.IsLeaveDay = 0
		AND tmpca.IsKeepInView = 0
		AND (
			(
				s.ShiftID IS NULL
				AND (
					(
						tmpws.IsOffDay = 1
						AND tmpca.IsOffDay = 0
						)
					OR (
						tmpws.IsOffDay = 0
						AND tmpca.IsOffDay = 1
						)
					OR (
						tmpws.IsHoliday = 1
						AND tmpca.IsHoliday = 0
						AND h.Id IS NOT NULL
						)
					OR (
						tmpws.IsHoliday = 0
						AND tmpca.IsHoliday = 1
						)
					)
				)
			OR (
				s.ShiftID IS NOT NULL
				AND (
					tmpca.ShiftId IS NULL
					OR tmpca.ShiftId != s.ShiftID
					)
				)
			)

	INSERT INTO dbo.EmployeeCalendar (
		WorkDate
		,EmpId
		,ShiftId
		,IsOffDay
		,IsHoliday
		,ModifiedBy
		,ModifiedDate
		,OWPSyncDate
		)
	OUTPUT INSERTED.EmpId
		,INSERTED.WorkDate
		,INSERTED.ShiftId
		,INSERTED.IsOffDay
		,INSERTED.IsHoliday
	INTO #tmpEmployeeCalendar(EmpId, WorkDate, ShiftId, IsOffDay, IsHoliday)
	SELECT DISTINCT tmpws.ShiftDate
		,e.EmpId
		,s.ShiftID
		,CASE 
			WHEN tmpca.EmpId IS NULL
				OR (
					tmpca.EmpId IS NOT NULL
					AND tmpca.IsLeaveDay = 0
					AND tmpca.IsKeepInView = 0
					AND tmpca.ChangeShiftTypeId IS NULL
					) THEN tmpws.IsOffDay
			ELSE 0
			END
		,CASE 
			WHEN tmpws.IsHoliday = 1
				AND h.Id IS NOT NULL THEN 1
			ELSE 0
			END
		,@ActorId
		,@SyncDate
		,@SyncDate
	FROM #tmpWorkingShift AS tmpws WITH (NOLOCK)
		INNER JOIN dbo.Employee AS e WITH (NOLOCK) ON e.Code = tmpws.EmployeeID
		INNER JOIN #tmpEmployeeIds AS tmpemp WITH (NOLOCK) ON e.EmpId = tmpemp.EmpId
		LEFT JOIN dbo.[Shift] AS s WITH (NOLOCK) ON s.Code = tmpws.ShiftCode
		LEFT JOIN dbo.Holiday AS h WITH (NOLOCK) ON tmpws.ShiftDate BETWEEN h.FromDate
			AND h.ToDate
		LEFT JOIN dbo.tmpEmployeeCalendar AS tmpca WITH (NOLOCK) ON e.EmpId = tmpca.EmpId
		AND CAST(tmpws.ShiftDate AS DATE) = CAST(tmpca.WorkDate AS DATE)
	WHERE (
			(
				s.ShiftID IS NULL
				AND (
					tmpws.IsOffDay = 1
					OR (
						tmpws.IsHoliday = 1
						AND h.Id IS NOT NULL
						)
					)
				)
			OR s.ShiftID IS NOT NULL
			)
		AND NOT EXISTS (
			SELECT ec.EmpId
			FROM dbo.EmployeeCalendar AS ec WITH (NOLOCK)
			WHERE ec.EmpId = e.EmpId
				AND CAST(tmpws.ShiftDate AS DATE) = CAST(ec.WorkDate AS DATE)
			)

	IF EXISTS (
			SELECT 1
			FROM #tmpEmployeeCalendar WITH (NOLOCK)
			)
	BEGIN
		EXEC dbo.ScheduleArrangement_UpdateOffDayReplacement @ActorId = @ActorId
			,@EmployeeIds = @EmployeeIds
			,@FromDate = @FromDate
			,@ToDate = @ToDate
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT

		DECLARE @xml NVARCHAR(MAX)

		SET @xml = CAST((
					SELECT EmpId AS '@EmpId'
						,WorkDate AS '@WorkDate'
						,ShiftId AS '@ShiftId'
						,IsOffDay AS '@IsOffDay'
						,IsHoliday AS '@IsHoliday'
					FROM #tmpEmployeeCalendar WITH (NOLOCK)
					FOR XML PATH('Row')
						,ROOT('Root')
					) AS NVARCHAR(MAX))

		EXEC dbo.Log_WriteLog @LogActionId = 1004
			,@LogDate = @SyncDate
			,@Description = 'Sync working shift from OWP'
			,@TrackingValue = @xml
			,@UserId = @ActorId
	END

	DELETE
	FROM #tmpEmployeeCalendar WITH (ROWLOCK, UPDLOCK)
	WHERE WorkDate > @Today

	WHILE EXISTS (
			SELECT 1
			FROM #tmpEmployeeCalendar WITH (NOLOCK)
			)
	BEGIN
		SELECT TOP 1 @EmpId = EmpId
			,@WorkDate = WorkDate
		FROM #tmpEmployeeCalendar WITH (NOLOCK)

		EXEC dbo.EmployeeAttendance_ProcessingAndInsert @EmpId
			,@WorkDate
			,@WorkDate
			,1

		DELETE
		FROM #tmpEmployeeCalendar WITH (ROWLOCK, UPDLOCK)
		WHERE EmpId = @EmpId
			AND WorkDate = @WorkDate
	END
	END TRY
	BEGIN CATCH
		SELECT @ErrMsg = ERROR_MESSAGE()
	END CATCH

	DROP TABLE #tmpEmployeeIds

	DROP TABLE #tmpWorkingShift

	DROP TABLE #tmpEmployeeCalendar
END

GO
/****** Object:  StoredProcedure [dbo].[ScheduleArrangement_UpdateDisplayOrder]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ScheduleArrangement_UpdateDisplayOrder] @ActorId INT
	,@DisplayOrderXml VARCHAR(MAX) = ''
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: Tim.Trinh@2019-04-17
Task: Update display order
DB: HRM
Original:

Revisions:
Param's Explanation:
    @DisplayOrderXml=N'<Root><Row EmployeeId="1" DisplayOrder="1" /></Root>

*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @ModifiedDate DATETIME = GETDATE()
		,@DocHandler INT

	CREATE TABLE #tblDisplayOrder (
		EmployeeId INT
		,DisplayOrder INT
		)

	BEGIN TRY
		EXEC sp_xml_preparedocument @DocHandler OUTPUT
			,@DisplayOrderXml

		INSERT INTO #tblDisplayOrder (
			EmployeeId
			,DisplayOrder
			)
		SELECT EmployeeId
			,DisplayOrder
		FROM OPENXML(@DocHandler, '/Root/Row', 1) WITH (EmployeeId INT, DisplayOrder INT) AS Data

		EXEC sp_xml_removedocument @DocHandler
	END TRY

	BEGIN CATCH
		SELECT @ErrCode = 100
			,@ErrMsg = N'Paramter invalid.'

		RETURN
	END CATCH;

	UPDATE sa
	SET sa.DisplayOrder = tbl.DisplayOrder
		,sa.ModifiedBy = @ActorId
		,ModifiedDate = @ModifiedDate
	FROM dbo.ScheduleArrangement AS sa WITH (ROWLOCK, UPDLOCK)
		INNER JOIN #tblDisplayOrder AS tbl ON sa.EmployeeId = tbl.EmployeeId
		AND ISNULL(sa.DisplayOrder, 0) <> tbl.DisplayOrder

	DELETE tbl
	FROM #tblDisplayOrder AS tbl
	WHERE EXISTS (
			SELECT 1
			FROM dbo.ScheduleArrangement AS sa WITH (NOLOCK)
			WHERE sa.EmployeeId = tbl.EmployeeId
				AND sa.DisplayOrder = tbl.DisplayOrder
			)

	INSERT INTO dbo.ScheduleArrangement (
		EmployeeId
		,DisplayOrder
		,ModifiedBy
		,ModifiedDate
		)
	SELECT EmployeeId
		,DisplayOrder
		,@ActorId
		,@ModifiedDate
	FROM #tblDisplayOrder

	DROP TABLE #tblDisplayOrder
END



GO
/****** Object:  StoredProcedure [dbo].[ScheduleArrangement_UpdateGroupOrder]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ScheduleArrangement_UpdateGroupOrder] @ActorId INT
	,@DisplayOrderXml VARCHAR(MAX) = ''
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: Tim.Trinh@2019-04-22
Task: Update group order
DB: HRM
Original:

Revisions:
Param's Explanation:
    @DisplayOrderXml=N'<Root><Row TeamId="1" DisplayOrder="1" /></Root>

*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @ModifiedDate DATETIME = GETDATE()
		,@DocHandler INT

	CREATE TABLE #tblDisplayOrder (
		TeamId INT
		,DisplayOrder SMALLINT
		)

	BEGIN TRY
		EXEC sp_xml_preparedocument @DocHandler OUTPUT
			,@DisplayOrderXml

		INSERT INTO #tblDisplayOrder (
			TeamId
			,DisplayOrder
			)
		SELECT TeamId
			,DisplayOrder
		FROM OPENXML(@DocHandler, '/Root/Row', 1) WITH (TeamId INT, DisplayOrder SMALLINT) AS Data

		EXEC sp_xml_removedocument @DocHandler
	END TRY

	BEGIN CATCH
		SELECT @ErrCode = 100
			,@ErrMsg = N'Paramter invalid.'

		RETURN
	END CATCH;

	UPDATE sa
	SET sa.DisplayOrder = tbl.DisplayOrder
		,sa.ModifiedBy = @ActorId
		,ModifiedDate = @ModifiedDate
	FROM dbo.ScheduleArrangementGroupOrder AS sa WITH (ROWLOCK, UPDLOCK)
		INNER JOIN #tblDisplayOrder AS tbl ON sa.GroupId = tbl.TeamId
		AND ISNULL(sa.DisplayOrder, 0) <> tbl.DisplayOrder

	DELETE tbl
	FROM #tblDisplayOrder AS tbl
	WHERE EXISTS (
			SELECT 1
			FROM dbo.ScheduleArrangementGroupOrder AS sa WITH (NOLOCK)
			WHERE sa.GroupId = tbl.TeamId
				AND sa.DisplayOrder = tbl.DisplayOrder
			)

	INSERT INTO dbo.ScheduleArrangementGroupOrder (
		GroupId
		,DisplayOrder
		,ModifiedBy
		,ModifiedDate
		)
	SELECT TeamId
		,DisplayOrder
		,@ActorId
		,@ModifiedDate
	FROM #tblDisplayOrder

	DROP TABLE #tblDisplayOrder
END
GO
