CREATE PROCEDURE [dbo].[TimeRecord_Insert] @EmpId INT
	,@RecordTime DATETIME
	,@InOutType BIT
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg VARCHAR(200) = '' OUTPUT
AS
/*
Created: 20160701@Quinn.Vo
Task: Insert Shift.
DB: NexEPA
Original: 

Revisions:  
Param's Explanation:

*/
BEGIN
	SET NOCOUNT ON;

	DECLARE @FromDate DATETIME
	DECLARE @ToDate DATETIME

	INSERT INTO [dbo].[TimeRecord] (
		EmpId
		,RecordTime
		,InOutType
		,InsertDate
		)
	VALUES (
		@EmpId
		,@RecordTime
		,@InOutType
		,GETDATE()
		)

	SET @FromDate = convert(VARCHAR(10), dateadd(d, - 2, @RecordTime), 111)
	SET @ToDate = convert(VARCHAR(10), @RecordTime, 111)

	EXEC EmployeeAttendance_ProcessingAndInsert @EmpId
		,@FromDate
		,@ToDate
		,0
END

