CREATE PROCEDURE [dbo].[WorkingTimeRequest_ApproveMultipleRequest] @Requests NVARCHAR(MAX) = NULL
	,@ActorId INT
	,@RoleId TINYINT
	,@Command TINYINT
	,@Comment NVARCHAR(500) = ''
	,@IsIgnoredViolate BIT = 0
	,@IsConfirmed BIT = 0
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: Drake.Doi@2020-04-10
Task: approve request
DB: HRM_SMS
Original:

Revisions:
Param's Explanation:
	@Requests:
        <ROOT>
            <Row RequestId='' RequestTypeID=''></Row>
        </ROOT>
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE
		-- request type
		@CheckInRequestTypeId TINYINT = 1
		,@CheckOutRequestTypeId TINYINT = 2
		,@LateInRequestTypeId TINYINT = 3
		,@EarlyOutRequestTypeId TINYINT = 4
		,@ChangeShiftRequestTypeId TINYINT = 5
		,@LeaveRequestTypeId TINYINT = 6
		,@KeepInViewRequestTypeId TINYINT = 7
		-- Discipline Type
		,@ChangeShift INT = 1
		,@MissingCheckInOut INT = 2
		,@LateIn INT = 3
		,@EarlyOut INT = 4
		,@Absent INT = 5
		,@UnpaidLeave INT = 6
		,@UnpaidLeaveAbsent INT = 8
		,@UnplannedLeave INT = 9
		,@WeekenLeave INT = 10

	CREATE TABLE #request (
		RequestId BIGINT
		,RequestTypeID TINYINT
		)

	IF ISNULL(@Requests, '') <> ''
	BEGIN
		BEGIN TRY
			DECLARE @DocHandler INT

			EXEC sp_xml_preparedocument @DocHandler OUTPUT
				,@Requests

			INSERT INTO #request (
				RequestId
				,RequestTypeID
				)
			SELECT DISTINCT RequestId
				,RequestTypeID
			FROM OPENXML(@DocHandler, '/Root/Row', 1) WITH (RequestId BIGINT, RequestTypeID TINYINT) AS Data

			EXEC sp_xml_removedocument @DocHandler
		END TRY

		BEGIN CATCH
			SELECT @ErrCode = 1
				,@ErrMsg = N'Parameter invalid.'

			RETURN
		END CATCH
	END
	ELSE
	BEGIN
		RETURN
	END

	DECLARE @RequestID BIGINT
		,@RequestTypeID TINYINT

	CREATE TABLE #Disciplines (
		WorkDate DATE
		,EmployeeId INT
		,DisciplineTypeId INT
		,IsIgnored VARCHAR(20)
		,IsConfirmed VARCHAR(20)
		)

	WHILE (
			EXISTS (
				SELECT TOP (1) RequestID
				FROM #request
				)
			)
	BEGIN
		SELECT TOP (1) @RequestID = RequestID
			,@RequestTypeID = RequestTypeID
		FROM #request

		IF @RoleId = 3 -- Approve
		BEGIN
			IF @RequestTypeId = @CheckInRequestTypeId
				OR @RequestTypeId = @CheckOutRequestTypeId
			BEGIN
				INSERT INTO #Disciplines (
					WorkDate
					,EmployeeId
					,DisciplineTypeId
					,IsIgnored
					,IsConfirmed
					)
				SELECT cio.OnDate
					,emp.EmpId
					,drule.DisciplineTypeId
					,@IsIgnoredViolate
					,@IsConfirmed
				FROM dbo.CheckInOutRequest AS cio WITH (NOLOCK)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON emp.EmpId = cio.EmpId
					INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND empsum.IsLocal = drule.IsLocal
					AND drule.DisciplineTypeId = @MissingCheckInOut
					AND drule.Value = 1
				WHERE cio.RequestId = @RequestID
			END
			ELSE IF @RequestTypeId = @LateInRequestTypeId
				OR @RequestTypeId = @EarlyOutRequestTypeId
			BEGIN
				INSERT INTO #Disciplines (
					WorkDate
					,EmployeeId
					,DisciplineTypeId
					,IsIgnored
					,IsConfirmed
					)
				SELECT lio.OnDate
					,emp.EmpId
					,drule.DisciplineTypeId
					,@IsIgnoredViolate
					,@IsConfirmed
				FROM dbo.WorkingTimeRequest AS wkr WITH (NOLOCK)
					INNER JOIN dbo.LateInEarlyOutRequest AS lio WITH (NOLOCK) ON wkr.RequestId = lio.RequestId
					AND lio.RequestId = @RequestId
					INNER JOIN dbo.EmployeeCalendar AS ca WITH (NOLOCK) ON ca.EmpId = wkr.EmpId
					AND CAST(ca.WorkDate AS DATE) = CAST(lio.OnDate AS DATE)
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON emp.EmpId = wkr.EmpId
					INNER JOIN dbo.EmployeeSummary AS emps WITH (NOLOCK) ON emp.EmpId = emps.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND emps.IsLocal = drule.IsLocal
					AND drule.Value = 1
					AND (
						wkr.RequestType = @LateInRequestTypeId
						OR (
							wkr.RequestType = @EarlyOutRequestTypeId
							AND ISNULL(ca.IsOffDay, 0) = 0
							AND ISNULL(ca.IsHoliday, 0) = 0
							)
						)
					AND (
						(
							wkr.RequestType = @LateInRequestTypeId
							AND drule.DisciplineTypeId = @LateIn
							)
						OR (
							wkr.RequestType = @EarlyOutRequestTypeId
							AND drule.DisciplineTypeId = @EarlyOut
							)
						)
			END
			ELSE IF @RequestTypeId = @ChangeShiftRequestTypeId
			BEGIN
				INSERT INTO #Disciplines (
					WorkDate
					,EmployeeId
					,DisciplineTypeId
					,IsIgnored
					,IsConfirmed
					)
				SELECT csdt.OnDate
					,csdt.EmpId
					,@ChangeShift
					,@IsIgnoredViolate
					,@IsConfirmed
				FROM dbo.ChangeShiftRequest AS cs WITH (NOLOCK)
					INNER JOIN dbo.ChangeShiftRequestDetail AS csdt WITH (NOLOCK) ON cs.RequestId = csdt.RequestId
					INNER JOIN dbo.Employee AS emp WITH (NOLOCK) ON emp.EmpId = cs.EmpId
					INNER JOIN dbo.EmployeeSummary AS empsum WITH (NOLOCK) ON emp.EmpId = empsum.EmpId
					INNER JOIN dbo.DisciplineGroupRule AS drule WITH (NOLOCK) ON emp.GroupId = drule.GroupId
					AND empsum.IsLocal = drule.IsLocal
					AND drule.DisciplineTypeId = @ChangeShift
					AND drule.Value = 1
				WHERE csdt.RequestId = @RequestID
					AND cs.TypeId = 1 -- Change Shift
			END
			ELSE IF @RequestTypeId = @LeaveRequestTypeId
			BEGIN
				INSERT INTO #Disciplines (
					WorkDate
					,EmployeeId
					,DisciplineTypeId
					,IsIgnored
					,IsConfirmed
					)
				SELECT WorkDate
					,lr.EmpId
					,CASE 
						WHEN IsUnpaidLeaveAbsent = 1 THEN @UnpaidLeaveAbsent
						WHEN IsAbsent = 1 THEN @Absent
						WHEN IsUnplannedLeave = 1 THEN @UnplannedLeave
						WHEN IsUnpaidLeave = 1 THEN @UnpaidLeave
						WHEN IsWeekendLeave = 1 THEN @WeekenLeave
						END AS DisciplineTypeId
					,CASE @IsIgnoredViolate
						WHEN 1 THEN 'True'
						ELSE 'False'
						END AS IsIgnoredViolate
					,CASE @IsConfirmed
						WHEN 1 THEN 'True'
						ELSE 'False'
						END AS IsConfirmed
				FROM [dbo].[fnc_GetDisciplineDetailByLeaveRequestId](@RequestID)
					INNER JOIN dbo.LeaveRequest AS lr WITH (NOLOCK) ON lr.RequestId = @RequestID
				WHERE IsUnpaidLeaveAbsent = 1
					OR IsAbsent = 1
					OR IsUnplannedLeave = 1
					OR IsUnpaidLeave = 1
					OR IsWeekendLeave = 1
			END
		END

		DECLARE @DisciplineXml NVARCHAR(MAX) = (
				SELECT *
				FROM #Disciplines
				FOR XML RAW('Row')
					,ROOT('Root')
				)

		EXECUTE WorkingTimeRequest_ApproveRequest @RequestID
			,@ActorId
			,@RoleId
			,@Comment
			,@DisciplineXml

		DELETE #request
		WHERE RequestId = @RequestID

		DELETE #Disciplines
	END

	DROP TABLE #Disciplines

	DROP TABLE #request
END

GO
/****** Object:  StoredProcedure [dbo].[WorkingTimeRequest_ApproveRequest]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[WorkingTimeRequest_ApproveRequest] @RequestId BIGINT
	,@ActorId INT
	,@RoleId TINYINT
	,@Comment NVARCHAR(500) = ''
	,@DisciplineXml NVARCHAR(MAX) = NULL
	,@ViewType NVARCHAR(50) = ''
	,@ErrCode INT = 0 OUTPUT
	,@ErrMsg NVARCHAR(200) = '' OUTPUT
AS
/*
Created: Tom.Vo@2013-11-06
Task: approve request
DB: HRM_SMS
Original:

Revisions:
Param's Explanation:
    @IgnoredDetails:
        <ROOT>
            <Discipline WorkDate='' EmployeeId='' DisciplineTypeId='' IsIgnored='' IsConfirmed=''></Discipline>
        </ROOT>
*/
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;

	DECLARE @EmpId INT
		,@RequestTypeId SMALLINT
		,@StatusId TINYINT
		,@VerifierId INT
		,@ApproverId INT
		-- system role
		,@VerifierRoleId TINYINT = 2
		,@ApproverRoleId TINYINT = 3
		,@HRRoleId TINYINT = 6
		,@SystemAdminRoleId TINYINT = 7
		-- request status
		,@PendingStatusId TINYINT = 1
		,@VerifiedStatusId TINYINT = 2
		,@ApprovedStatusId TINYINT = 4
		-- request type
		,@CheckInRequestTypeId TINYINT = 1
		,@CheckOutRequestTypeId TINYINT = 2
		,@LateInRequestTypeId TINYINT = 3
		,@EarlyOutRequestTypeId TINYINT = 4
		,@ChangeShiftRequestTypeId TINYINT = 5
		,@LeaveRequestTypeId TINYINT = 6
		,@KeepInViewRequestTypeId TINYINT = 7
		-- view Type
		,@HRSpace NVARCHAR(50) ='HRSpace'

	SELECT @EmpId = EmpId
		,@RequestTypeId = RequestType
		,@StatusId = CurrentStatus
		,@VerifierId = VerifierId
		,@ApproverId = ApproverId
	FROM dbo.WorkingTimeRequest WITH (NOLOCK)
	WHERE RequestId = @RequestId

	IF @RoleId = @VerifierRoleId
		AND (
			@StatusId <> @PendingStatusId
			OR @VerifierId <> @ActorId
			)
	BEGIN
		SELECT @ErrCode = 100
			,@ErrMsg = 'You can not verify this request.'

		RETURN
	END

	IF @RoleId = @ApproverRoleId
		AND (
			@StatusId NOT IN (@PendingStatusId, @VerifiedStatusId)
			OR (@ApproverId <> @ActorId AND @ViewType != @HRSpace)
			)
	BEGIN
		SELECT @ErrCode = 101
			,@ErrMsg = 'You can not approve this request.'

		RETURN
	END

	IF @RoleId = @HRRoleId
		AND (
			@StatusId <> @ApprovedStatusId
			OR NOT EXISTS (
				SELECT 1
				FROM dbo.EmployeeRole WITH (NOLOCK)
				WHERE EmployeeId = @ActorId
					AND RoleId IN (@HRRoleId, @SystemAdminRoleId)
				)
			)
	BEGIN
		SELECT @ErrCode = 102
			,@ErrMsg = 'You can not process this request.'

		RETURN
	END

	IF @RequestTypeId = @CheckInRequestTypeId
		OR @RequestTypeId = @CheckOutRequestTypeId
	BEGIN
		EXEC dbo.CheckInOutRequest_Approve @RequestId = @RequestId
			,@RoleId = @RoleId
			,@ActorId = @ActorId
			,@DisciplineXml = @DisciplineXml
			,@Comment = @Comment
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END
	ELSE IF @RequestTypeId = @LateInRequestTypeId
		OR @RequestTypeId = @EarlyOutRequestTypeId
	BEGIN
		EXEC dbo.LateInEarlyOutRequest_Approve @RequestId = @RequestId
			,@RoleId = @RoleId
			,@ActorId = @ActorId
			,@DisciplineXml = @DisciplineXml
			,@Comment = @Comment
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END
	ELSE IF @RequestTypeId = @ChangeShiftRequestTypeId
	BEGIN
		EXEC dbo.ChangeShiftRequest_Approve @RequestId = @RequestId
			,@RoleId = @RoleId
			,@ActorId = @ActorId
			,@DisciplineXml = @DisciplineXml
			,@Comment = @Comment
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END
	ELSE IF @RequestTypeId = @LeaveRequestTypeId
	BEGIN
		EXEC dbo.LeaveRequest_Approve @RequestId = @RequestId
			,@RoleId = @RoleId
			,@ActorId = @ActorId
			,@DisciplineXml = @DisciplineXml
			,@Comment = @Comment
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END
	ELSE IF @RequestTypeId = @KeepInViewRequestTypeId
	BEGIN
		EXEC dbo.KeepInViewRequest_Approve @RequestId = @RequestId
			,@RoleId = @RoleId
			,@ActorId = @ActorId
			,@Comment = @Comment
			,@ErrCode = @ErrCode OUTPUT
			,@ErrMsg = @ErrMsg OUTPUT
	END
END





GO
/****** Object:  StoredProcedure [dbo].[WorkingTimeRequest_GetNewRefNoByRequestType]    Script Date: 2/13/2025 1:39:31 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[WorkingTimeRequest_GetNewRefNoByRequestType] @RefNo NVARCHAR(100) = NULL OUTPUT
	,@RequestType INT = NULL
AS
/*
Created: Tom.Vo@2013-11-05
Task: Get New RefNo From Request Type
DB: HRM_SMS
Original: 

Revisions:    
Param's Explanation:
	
*/
BEGIN
	SET NOCOUNT ON;

	IF @RequestType = 6
		SELECT @RefNo = Max(RefNo)
		FROM dbo.LeaveRequest r WITH (NOLOCK)
			INNER JOIN dbo.WorkingTimeRequest wr WITH (NOLOCK) ON r.RequestId = wr.RequestId
	ELSE IF @RequestType = 7
		SELECT @RefNo = Max(RefNo)
		FROM dbo.KeepInViewRequest r WITH (NOLOCK)
			INNER JOIN [dbo].WorkingTimeRequest wr WITH (NOLOCK) ON r.RequestId = wr.RequestId

	DECLARE @Num INT

	--Ref-000001
	IF ISNULL(@RefNo, '') = ''
		SET @RefNo = CASE 
				WHEN @RequestType = 6 THEN 'Ref-000001'
				WHEN @RequestType = 7 THEN 'KIV-000001'
				ELSE 'Ref-000001'
				END
	ELSE
	BEGIN
		SET @Num = CONVERT(INT, RIGHT(@RefNo, LEN(@RefNo) - 4)) + 1
		SET @RefNo = CASE 
				WHEN @RequestType = 6 THEN 'Ref-'
				WHEN @RequestType = 7 THEN 'KIV-'
				ELSE 'Ref-'
				END + REPLICATE('0', 6 - LEN(@Num)) + CONVERT(NVARCHAR(100), @Num)
	END
END



